/* 珍珠奶茶 */
(window.TB_LESSONS = window.TB_LESSONS || []).push(["珍珠奶茶", {"title": "當代 焦桐〈珍珠奶茶〉", "author": {"dynasty": "當代", "name": "焦桐", "intro": "", "context": "本文節選自《臺灣肚皮》，書中逐一介紹臺灣各地小吃、茶飲，透過日常庶民飲食的深刻觀察，及其背後動人故事，帶領讀者一窺臺灣雜揉四海、兼容並蓄的文化面貌。作者將飲食文學聚焦在地方性的書寫，蒐羅當代諸多著名的小吃，用食物來描寫臺灣的性格、文化及主體性。"}, "extras": {"intro": [{"label": "題解·課本", "head": "題解", "body": "本文節選自《臺灣肚皮》，書中逐一介紹臺灣各地小吃、茶飲，透過日常庶民飲食的深刻觀察，及其背後動人故事，帶領讀者一窺臺灣雜揉四海、兼容並蓄的文化面貌。作者將飲食文學聚焦在地方性的書寫，蒐羅當代諸多著名的小吃，用食物來描寫臺灣的性格、文化及主體性。<br><br>「珍珠奶茶」是臺灣最具代表性的手搖茶飲，近年來更風靡國際，在亞洲、歐洲、美國乃至中東國家流行，成為臺灣文化的一部分，既創新也帶動臺灣茶飲的國際化。本文介紹珍珠奶茶的起源發展、飲用方式及文化意義，並探討伴隨著流行而出現的食安問題。"}], "authorPages": [{"label": "作者·課本", "head": "作者", "body": "焦桐，本名葉振富，高雄人，民國四十五年生。文化大學 戲劇系、藝術所碩士畢業，輔仁大學 比較文學研究所博士班肄業。曾任教中央大學 中國文學系，早年從事報紙、雜誌的編輯工作，退休後專事寫作。<br><br>焦桐在《完全壯陽食譜》詩集出版後，展現對飲食文學的深厚興趣並著力推廣，後來成立「二魚文化」，創辦《飲食》雜誌，為當代飲食文學的重要推手。近年來更關注食安問題，強調健康的飲食觀念，重視下一代飲食文化的教育。<br><br>詩作題材多元，意象鮮明，善用戲謔手法嘲諷政治；散文藉自身飲食經驗，書寫食後感懷與賞評，探索社會議題及人生況味，充滿人文情懷。著有詩集《完全壯陽食譜》、《青春標本》、《焦桐詩集：1980～1993》，散文集《暴食江湖》、《臺灣肚皮》、《味道福爾摩莎》、《慢食天下》等。"}], "appreciation": [{"label": "賞析·課本", "head": "賞析", "body": "本文探討珍珠奶茶的發展史，這種結合了茶香、奶香和Q彈珍珠的飲品，不僅是臺灣街頭巷尾常見的飲料，更是一種文化符號，展現臺灣飲食的創新與融合。特色如下：<br><br>一、綜觀古今歷史文化：透過回顧歷史，探討奶茶可能的起源，說明奶茶在中國文化中的地位和價值；並以珍奶流行國際，凸顯其掀起的風潮。<br><br>二、結合健康養生價值：從中醫的角度分析奶茶的養生價值，指出奶茶幫助北方游牧民族改善消化不良、營養失調的問題，從而探討飲食與健康的關係。<br><br>三、揭示食品安全問題：作者提及商家為追求利潤，在珍珠的製作過程中添加塑化劑等有害物質，警示消費者應關注食品安全，以維護健康。<br><br>四、融合情感與事實：本文有主觀的個人觀點和情感，如對珍珠奶茶的愛好、食品安全問題的擔憂、飲食文化和商業化的反思；除此之外，也有客觀的製作過程描述，使文章更加生動和具有感染力。<br><br>本文整體結構清晰，段落之間流暢連接，透過對不同主題的討論，讓讀者更能全面了解珍珠奶茶及食安相關議題。"}], "supplement": [], "questions": [], "exams": [], "reviewQ": [{"q": "珍珠奶茶的流行帶動許多商機，就你的觀察，有哪些食品與珍奶相關？請簡單分享。", "a": "（開放作答，可依課文與生活經驗發揮）"}, {"q": "食品中的添加物可能對人體產生不良的影響，消費者在選擇時，應更加關注成分。請選擇一種你常吃的零食，搜尋其標示的原料，並分享你的看法。", "a": "（開放作答，可依課文與生活經驗發揮）"}]}, "textPages": [{"seg": "第1部分", "title": "一、發明與製作", "book": "課本 P.62", "lines": [{"text": "臺灣人在一九八○年代發明了珍珠奶茶：冰紅茶摻入牛奶、糖，再加上粉圓。四十年來，形式變化甚微，倒是增添了不少口味，作為{n:1|基底}的茶品也多了綠茶、各式花茶和熱飲。"}, {"text": "珍珠就是大顆的粉圓，乃黑糖漿、地瓜粉或{n:2|木薯}粉再製；傳統製法是地瓜粉和水拌勻，再搓揉成粒狀，然後以篩網篩出即成。後來發展出的同類產品還有「青蛙下蛋」、「波霸奶茶」。"}], "notes": [["基底", "主要的成分。"], ["木薯", "又稱「樹薯」，可供食用或製粉，並為酒精及味精之主要原料。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第2部分", "title": "二、歷史背景", "book": "課本 P.62~P.63", "lines": [{"text": "奶和茶的結合可能起源於唐代。當年{n:1|文成公主}下嫁{n:2|松贊干布}，帶去茶葉，傳授當地人烹茶技術，並用牛奶、羊奶熬煮茶葉，據說他們愛死了這種清香美味的奶茶，已經到了「{n:3|寧可三日無糧，不可一日無茶}」的地步。"}, {"text": "不僅美味，其中還存在著養生的道理。中醫觀點認為奶茶能解腥去{n:4|膻}、清內熱。北方的游牧民族長期吃肉，體內維生素和{n:5|無機鹽}不足，導致營養失調、消化不良；喝奶茶剛好可以緩解這些現象。"}, {"text": "清代的皇室祭祀，都要奉一碗奶茶來表示敬意。宮廷筵席還把賜奶茶作為隆重的禮儀制度。為了敬重奶茶，乾隆皇帝有一只白玉鑲紅寶石的奶茶碗，專門在重要筵席上自己喝奶茶或賜奶茶用的；這只碗使用完美無瑕的{n:6|和闐玉}製作，在碗外壁近底部和{n:7|圈足}表面，{n:8|錯飾}金片的花草，並用紅寶石嵌成花瓣。"}], "notes": [["文成公主", "唐太宗的宗室女（？～西元六八○），篤信佛教，貞觀十四年嫁吐蕃（今西藏）國王棄宗弄贊。"], ["松贊干布", "即棄宗弄贊（西元六一七～六五○），唐時吐蕃國王。慷慨有雄才，對該族宗教、文化貢獻很大。"], ["寧可三日無糧不可一日無茶", "藏語俗諺，表示對茶的熱衷。"], ["膻", "同「羶」。羊身上的臊味。"], ["無機鹽", "即礦物質，用以維持正常生理作用。"], ["和闐玉", "崑崙山北麓和闐所產的美玉。"], ["圈足", "器物底部接觸放置面的部位，成一圈形而得名。"], ["錯飾", "鑲金或塗金的裝飾。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第3部分", "title": "三、製作方式與美味關鍵", "book": "課本 P.64", "lines": [{"text": "「我的馬丁尼用搖的，不用攪的」（‟I want martini shake, not stirred”），好萊塢電影007情報員以這句經典臺詞表露品味，他身邊隨時圍繞著性感美女，大概是天下男人的偶像了。珍珠奶茶就是用搖的，不能隨便亂攪和。我愛看業者用{n:1|雪克}器搖茶，動作瀟灑帥氣，帶著表演性質，總覺得像一種舞蹈。"}, {"text": "既是粉圓、奶茶{n:2|連袂}演出，美味關鍵主要在兩者的品質，奶茶須新鮮香醇，避免用奶精、糖精；粉圓的口感講究彈勁，不可黏稠，更不可摻加人工合成{n:3|塑化劑}。"}, {"text": "珍珠奶茶的前身是泡沫紅茶，以中國醫藥大學斜對面的「雙江茶行」為佳，其泡沫紅茶、水果紅茶都讚。店家每次用小桶沖泡紅茶，怪不得珍珠奶茶能有獨特的茶香，現泡現賣。"}], "notes": [["雪克", "英文shake的音譯，搖，調製飲料的專門用語。"], ["連袂", "比喻共同動作。"], ["塑化劑", "或稱增塑劑、可塑劑，是一種增加材料的柔軟性或使材料液化的添加劑，並非合法的食品添加物。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第4部分", "title": "四、全球影響", "book": "課本 P.65~P.66", "lines": [{"text": "珍珠奶茶是臺灣年輕人生活中不可短缺的冷飲，街巷隨處可見店家，夜市也不乏攤販。可惜它不適合我這種血糖偏高的肥仔，我只好假裝不喜歡喝。從前有一個同事每天要喝兩大杯這類飲料，奇怪竟能保持身材，只能嫉妒他{n:1|天賦異稟}了。"}, {"text": "我在上海、澳門看到臺灣的珍珠奶茶也大受歡迎，忽然升起榮耀感，一種奇怪的認同感。如今珍珠奶茶已風行亞洲、歐洲、美國甚至中東國家；{n:2|倫敦 蘇活區}（SOHO）珍珠奶茶店‟Bubbleology”生意興隆，其原料、包裝都來自臺灣，老闆Assad熱愛臺灣文化，自謂是臺灣養子。"}, {"text": "臺中市「春水堂」說他們是珍珠奶茶的發源店，臺南「翰林茶館」負責人涂宗和說他才是珍珠奶茶的發明人。可惜這兩家店當初都未申請專利，就像臺中「太陽堂」太陽餅，全世界賣太陽餅的都可自稱太陽堂本店。"}], "notes": [["天賦異稟", "天生的資質特優，超出於尋常。"], ["倫敦蘇活區", "位於倫敦西區，有劇院、咖啡館、餐廳、酒吧和俱樂部，提供各式餐飲、消費、娛樂的選擇。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第5部分", "title": "五、品質問題", "book": "課本 P.66~P.67", "lines": [{"text": "我不在乎誰發明了珍珠奶茶，只在乎誰認真泡茶？在乎誰老老實實製作？由於地瓜粉或木薯粉，都不能令粉圓產生彈牙的嚼感，大部分商家遂添加人工合成塑化劑。"}, {"text": "市售奶茶多含香料、增稠劑等添加物，也漸漸以人造奶精取代鮮乳，奶精含{n:1|反式脂肪酸}，奶味濃郁；那是一種娛樂食物（eatertainment）。娛樂食物多含高熱量、高脂肪、高鹽，這種東西很狡猾，從不呈現食物的原味，{n:2|念茲在茲}僅僅是要添加什麼，以全方位滿足人們味覺的快感。像習慣欺瞞的人不會講出真誠的話，當味覺被香料和增稠劑欺瞞慣了，就再也難以接受誠懇而美好的味道。"}, {"text": "許多食品加工業者、餐館為了追求最大利潤，罔顧後果的降低成本，竟在飲料、食品中摻入塑化劑。新聞爆發後，我憤怒難抑，鬱悶難紓。我的長女今年24歲，她已經吃了24年的塑化劑；我的么女今年12歲，她吃了12年的塑化劑。甚至連感冒發燒時，醫生總是建議：給她喝運動飲料。我不敢想像這些毒物如何毒害她們的身體。黑心商人的事業越做越大，我們的健康越來越糟。"}], "notes": [["反式脂肪酸", "一種不飽和脂肪酸，會升高成分不佳的壞膽固醇，增加罹患心血管疾病（如動脈硬化、心臟病等）的風險。"], ["念茲在茲", "指對某人或某事牢記在心，念念不忘。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第6部分", "title": "六、價格與價值", "book": "課本 P.67~P.68", "lines": [{"text": "食品價格無所謂昂貴或便宜，端視它合不合理。諸如用化學藥劑促長的香菇，3個月即可收成；以{n:1|自然農耕法}培育的香菇需費時12個月才能收成，它們的價格豈能一樣？兩者間的風味、營養、安全當然也{n:2|迥異}。"}, {"text": "網友有時會罵頂級餐館賣得太貴，其實應該考慮的是合理與否；頂級餐館的獲利，往往遠不如一般連鎖餐館。形式是最容易模仿的，低級餐館往往以廉價食材模擬了高級餐館的形式，再用相對較便宜的價格{n:3|招徠}不察的顧客；同樣是供應套餐，都有沙拉、前菜、湯、主菜、甜點、飲料，各家餐館呈現的每一種食材、每一個細節卻都存在著極大的落差；吾人學習飲食之道，無非是學習知味辨味，理解食物及其操作。"}], "notes": [["自然農耕法", "指不施用農藥或化學肥料，以天然資材防蟲與制菌的耕作方法。"], ["迥異", "不相同。"], ["招徠", "吸引招攬。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}, {"seg": "第7部分", "title": "七、搭配美感", "book": "課本 P.68~P.69", "lines": [{"text": "珍珠奶茶之發明，表現一種粉圓與奶茶的搭配美感，這類例子不少，諸如泡菜與臭豆腐，油條與豆漿，大蒜與香腸，米酒之於{n:1|四臣湯}、五味醬之於章魚……"}, {"text": "優質的珍珠奶茶，上面總是一層綿密的奶泡，同時表現茶香和奶香，兩者又能快樂的平衡。它取悅味蕾如同一場優美的舞蹈。粉圓{n:2|徜徉}在茶湯中，吸吮入嘴，輕柔撫觸舌尖，滑動，像舌頭之外另一個舌頭。每一顆粉圓溜進嘴裡都像一次甜蜜的吻。"}], "notes": [["四臣湯", "即「四神湯」，一般以芡實、蓮子、淮山、茯苓燉煮豬肚而成。"], ["徜徉", "安閒自在的徘徊。"]], "pian": "", "xi": "", "fan": "", "qa": [], "ask": [], "askT": ""}], "aHand": {"title": "第一部分：非選擇題（共 22 分）", "secs": [{"h": "一、字音字形（每題 2 分，共 12 分）", "items": [["1", "連「袂」", "ㄇㄟˋ"], ["2", "吸「吮」", "ㄕㄨㄣˇ"], ["3", "解腥去「膻」", "ㄕㄢ"], ["4", "兼容並「ㄒㄩˋ」", "蓄"], ["5", "「ㄘㄨㄛ」揉", "搓"], ["6", "宮廷「ㄧㄢˊ」席", "筵"]]}, {"h": "二、解釋（每題 2 分，共 10 分）", "items": [["1", "連袂", "比喻共同動作。"], ["2", "天賦異稟", "天生的資質特優，超出於尋常。"], ["3", "念茲在茲", "指對某人或某事牢記在心，念念不忘。"], ["4", "招徠", "吸引招攬。"], ["5", "徜徉", "安閒自在的徘徊。"]]}]}, "aQuiz": [{"n": 1, "ans": "D", "stem": "下列各組「 」中的注音寫成國字，何者字形相同", "opts": [["A", "「ㄙㄨˋ」化劑／推本「ㄙㄨˋ」源"], ["B", "「ㄧㄢˊ」席／蜿「ㄧㄢˊ」"], ["C", "完美無「ㄒㄧㄚˊ」／好整以「ㄒㄧㄚˊ」"], ["D", "味「ㄌㄟˇ」／花「ㄌㄟˇ」"]], "exp": "(A)塑／溯。推本溯源：推求根本，找尋源頭。形容探求事物的源頭起因。(B)筵／蜒。①蜿蜒：蛇類行走的樣子。②曲折延伸的樣子。(C)瑕／暇。好整以暇：原指軍隊步伐嚴整，從容不迫。後多以形容在紛亂、繁忙中顯得從容不迫。(D)蕾。", "trans": "", "per": {"A": "塑／溯。推本溯源：推求根本，找尋源頭。形容探求事物的源頭起因。", "B": "筵／蜒。①蜿蜒：蛇類行走的樣子。②曲折延伸的樣子。", "C": "瑕／暇。好整以暇：原指軍隊步伐嚴整，從容不迫。後多以形容在紛亂、繁忙中顯得從容不迫。", "D": "蕾。"}, "psg": "", "need_img": false}, {"n": 2, "ans": "C", "stem": "下列「 」中的詞語經替換後，何者意義最相近", "opts": [["A", "頂級餐館的「獲利」，往往遠不如一般連鎖餐館／福利"], ["B", "四十年來，形式變化「甚微」／式微"], ["C", "在碗外壁近底部和圈足表面，「錯飾」金片的花草／裝飾"], ["D", "粉圓徜徉在茶湯中，吸吮入嘴，輕柔「撫觸」舌尖／撫慰"]], "exp": "(A)獲利：取得利益。(B)式微：衰落、衰微。通常用以稱國勢、門祚、事業或某種社會運動的衰落。(D)撫觸：用手撫弄輕觸／撫慰：安撫慰勉。", "trans": "", "per": {"A": "獲利：取得利益。", "B": "式微：衰落、衰微。通常用以稱國勢、門祚、事業或某種社會運動的衰落。", "D": "撫觸：用手撫弄輕觸／撫慰：安撫慰勉。"}, "psg": "", "need_img": false}, {"n": 3, "ans": "C", "stem": "下列文句，何者沒有語病", "opts": [["A", "臺灣的珍珠奶茶口味罄竹難書，有許多不同的選擇"], ["B", "那家餐館的料理不僅美味，反而還有養生的功效"], ["C", "珍珠奶茶在臺灣遠近馳名，夜市中不乏販售珍珠奶茶的攤商"], ["D", "他做事總是十分謹慎，非得罔顧後果才能夠行動"]], "exp": "(A)罄竹難書：指罪惡多的數不清。可改為「不勝枚舉」（事物太多，不能一一舉出）。(B)「反而」應用在文意轉折，此處應改為「甚至」。(D)罔顧後果：指不顧後果。可改為「深思熟慮」（仔細而深入的考慮）。", "trans": "", "per": {"A": "罄竹難書：指罪惡多的數不清。可改為「不勝枚舉」（事物太多，不能一一舉出）。", "B": "「反而」應用在文意轉折，此處應改為「甚至」。", "D": "罔顧後果：指不顧後果。可改為「深思熟慮」（仔細而深入的考慮）。"}, "psg": "", "need_img": false}, {"n": 4, "ans": "D", "stem": "閱讀下文，推斷□□□□內最適合填入的詞語依序為何？", "opts": [["A", "歷經滄桑／新鶯出谷／駕輕就熟"], ["B", "口乾舌燥／廟堂之器／歷經滄桑"], ["C", "新鶯出谷／歷經滄桑／大雅之堂"], ["D", "駕輕就熟／大雅之堂／口乾舌燥"]], "exp": "由「不懂什麼茶道、從無相關經驗」可推斷無豐富經驗閱歷，因此填「駕輕就熟」較為適當╱由「不登……的茶葉梗」中粗劣的茶葉梗，可知填「大雅之堂」較為適當╱最後由「飲料」，而且只要喝茶，可說明「口乾舌燥」的現象，故選(D)。(A)歷經滄桑：比喻經歷無數事故與變化╱新鶯出谷：比喻人的歌聲，宛轉清脆，悅耳動聽，如黃鶯在山谷間鳴叫般╱駕輕就熟︰比喻對事情很熟悉，做起來很容易。(B)口乾舌燥︰嘴巴因缺乏水分而覺得乾燥口渴╱廟堂之器︰國寶。比喻可擔當大任的才具。(C)大雅之堂：風雅人物聚會的廳堂，借指高雅的境界。", "trans": "", "per": {"A": "歷經滄桑：比喻經歷無數事故與變化╱新鶯出谷：比喻人的歌聲，宛轉清脆，悅耳動聽，如黃鶯在山谷間鳴叫般╱駕輕就熟︰比喻對事情很熟悉，做起來很容易。", "B": "口乾舌燥︰嘴巴因缺乏水分而覺得乾燥口渴╱廟堂之器︰國寶。比喻可擔當大任的才具。", "C": "大雅之堂：風雅人物聚會的廳堂，借指高雅的境界。"}, "psg": "　　我不善品茶，不通茶經，更不懂什麼茶道，從無□□□□的相關經驗。但是，數十年來，喝過不少茶，北平的雙窨、天津的大葉、西湖的龍井、六安的瓜片……等，甚至不登□□□□的茶葉梗與滿天星隨壺淨的高末兒，都嘗試過。茶是我們中國人的飲料，一旦□□□□，惟茶是尚，人無貴賤，誰都有分，上焉者細啜名種，下焉者牛飲茶湯。<div class='aq-src'>（改寫自梁實秋〈喝茶〉）</div>", "need_img": false}, {"n": 5, "ans": "B", "stem": "若要使下文的理路連貫有序，①、②、③、④、⑤最適當的排列應是：", "opts": [["A", "①④③②⑤"], ["B", "②③⑤④①"], ["C", "③①④⑤②"], ["D", "⑤①③②④"]], "exp": "由提及「明治初年」可推論接②③，「迄今……依然……」。接下來論述古法內涵，便是接⑤，描述以新鮮艾草揉製，成果為④①，腴軟豐盈、蒼翠芳馨，故選(B)。", "trans": "", "per": {"B": "由提及「明治初年」可推論接②③，「迄今……依然……」。接下來論述古法內涵，便是接⑤，描述以新鮮艾草揉製，成果為④①，腴軟豐盈、蒼翠芳馨，故選(B)。"}, "psg": "　　東京有家「志滿草餅」，是明治初年的老鋪，　①蒼翠芳馨，②迄今一百多年，③依然恪守古法，④做出來腴軟豐盈，⑤用新鮮艾草揉製，　是我吃過最美味的草餅。<div class='aq-src'>（節錄自《蔡珠兒．艾之味》）</div>", "need_img": false}, {"n": 6, "ans": "C", "stem": "在語文中把兩種不同的、特別是相反的觀念或事實，對列起來兩相比較，從而使語氣增強，使意義明顯的修辭法，稱為「映襯」。下列文句何者使用映襯修辭", "opts": [["A", "粉圓徜徉在茶湯中，吸吮入嘴，輕柔撫觸舌尖，滑動"], ["B", "每一顆粉圓溜進嘴裡都像一次甜蜜的吻"], ["C", "用化學藥劑促長的香菇，3 個月即可收成；以自然農耕法培育的香菇需費時 12 個月才能收成"], ["D", "我不在乎誰發明了珍珠奶茶，只在乎誰認真泡茶？在乎誰老老實實製作"]], "exp": "(A)轉化（擬人）。(B)譬喻。(D)設問。", "trans": "", "per": {"A": "轉化（擬人）。", "B": "譬喻。", "D": "設問。"}, "psg": "", "need_img": false}, {"n": 7, "ans": "D", "stem": "「『我的馬丁尼用搖的，不用攪的』，好萊塢電影 007 情報員以這句經典臺詞表露品味。」其中「馬丁尼」是直接翻譯原詞 martini 的「音譯詞」用法，下列文句何者也是使用「音譯詞」", "opts": [["A", "我在上海、澳門看到臺灣的珍珠奶茶也大受歡迎，忽然升起榮耀感，一種奇怪的認同感"], ["B", "我不敢想像這些毒物如何毒害她們的身體。黑心商人的事業越做越大，我們的健康越來越糟"], ["C", "既是粉圓、奶茶連袂演出，美味關鍵主要在兩者的品質"], ["D", "我愛看業者用雪克器搖茶，動作瀟灑帥氣，帶著表演性質"]], "exp": "(D)雪克，英文 shake 的音譯，搖。", "trans": "", "per": {"D": "雪克，英文 shake 的音譯，搖。"}, "psg": "", "need_img": false}, {"n": 8, "ans": "B", "stem": "「食品價格無所謂昂貴或便宜，端視它合不合理。諸如用化學藥劑促長的香菇，3 個月即可收成；以自然農耕法培育的香菇需費時 12 個月才能收成，它們的價格豈能一樣？」此段文句主要說明何種觀點", "opts": [["A", "讚嘆科技的進步，縮短農作物的成長週期"], ["B", "說明價格反映品質和安全性，消費者要謹慎選擇"], ["C", "批評農民不務正業，為了賺錢違法使用化學藥劑"], ["D", "感傷食品價格不合理，特別是自然培育的香菇價格居高不下"]], "exp": "(B)由「食品價格無所謂昂貴或便宜，端視它合不合理」，以及比較化學藥劑和自然培育的香菇生產成本不同，呼籲消費者要謹慎選擇。", "trans": "", "per": {"B": "由「食品價格無所謂昂貴或便宜，端視它合不合理」，以及比較化學藥劑和自然培育的香菇生產成本不同，呼籲消費者要謹慎選擇。"}, "psg": "", "need_img": false}, {"n": 9, "ans": "D", "stem": "「一碗牛肉麵的屬性宛如一段旋律，我漸漸相信，天下美食都力求臻於音樂的境界，通過身體的味覺和消化系統，使精神達到幸福的狀態。」（焦桐〈論牛肉麵〉）上述文句描述美味的牛肉麵就像音樂優美的旋律，帶來精神上的幸福，下列何者也是描述類似的情懷", "opts": [["A", "奶茶能解腥去膻、清內熱。北方的游牧民族長期吃肉，體內維生素和無機鹽不足，導致營養失調、消化不良；喝奶茶剛好可以緩解這些現象"], ["B", "珍珠奶茶是臺灣年輕人生活中不可短缺的冷飲，街巷隨處可見店家，夜市也不乏攤販。可惜它不適合我這種血糖偏高的肥仔"], ["C", "「我的馬丁尼用搖的，不用攪的。」好萊塢電影 007 情報員以這句經典臺詞表露品味，他身邊隨時圍繞著性感美女，大概是天下男人的偶像了"], ["D", "（珍珠奶茶）取悅味蕾如同一場優美的舞蹈。粉圓徜徉在茶湯中，吸吮入嘴，輕柔撫觸舌尖，滑動，像舌頭之外另一個舌頭"]], "exp": "(D)珍珠奶茶可以取悅味蕾，如同一場優美的舞蹈，帶來肉體與精神上的幸福。", "trans": "", "per": {"D": "珍珠奶茶可以取悅味蕾，如同一場優美的舞蹈，帶來肉體與精神上的幸福。"}, "psg": "", "need_img": false}, {"n": 10, "ans": "C", "stem": "「我在上海、澳門看到臺灣的珍珠奶茶也大受歡迎，忽然升起榮耀感，一種奇怪的認同感……倫敦蘇活區珍珠奶茶店〝 Bubbleology 〞生意興隆，其原料、包裝都來自臺灣，老闆 Assad 熱愛臺灣文化，自謂是臺灣養子。」其中「奇怪的認同感」意謂下列何者", "opts": [["A", "認同如 Assad 般的臺灣人到國外獨自創業的勇氣"], ["B", "認同 Bubbleology 珍珠奶茶店到上海、澳門拓展店面的企圖心"], ["C", "認同臺灣產品品質受到國際肯定的驕傲"], ["D", "認同倫敦的珍珠奶茶店皆使用與當地口味相符的進口原料"]], "exp": "(C)描述作者連到上海、澳門都可以看到臺灣的珍珠奶茶，而且倫敦的珍珠奶茶店也使用臺灣的原料和包裝，讓作者因此感到臺灣產品品質風行國際的驕傲。", "trans": "", "per": {"C": "描述作者連到上海、澳門都可以看到臺灣的珍珠奶茶，而且倫敦的珍珠奶茶店也使用臺灣的原料和包裝，讓作者因此感到臺灣產品品質風行國際的驕傲。"}, "psg": "", "need_img": false}, {"n": 11, "ans": "B", "stem": "「以中國醫藥大學斜對面的『雙江茶行』為佳，其泡沫紅茶、水果紅茶都讚。店家每次用小桶沖泡紅茶，怪不得珍珠奶茶能有獨特的茶香，現泡現賣。」下列說明何者正確", "opts": [["A", "小桶便於儲存，能夠大量沖泡紅茶"], ["B", "小桶沖泡能更精確控制每批茶的品質"], ["C", "所有珍珠奶茶的統一作法皆為以小桶沖泡"], ["D", "中國醫藥大學的珍珠奶茶有獨特的風味"]], "exp": "(A)依據「現沖現泡」可知不是用來儲存。(B)小桶沖泡較能控制水溫，使每一杯茶的濃度和風味一致，更精確控制每批茶的品質，避免因大量沖泡而導致品質不穩定。(C)是雙江茶行的獨特作法。(D)文中並未提及中國醫藥大學有販售珍珠奶茶。", "trans": "", "per": {"A": "依據「現沖現泡」可知不是用來儲存。", "B": "小桶沖泡較能控制水溫，使每一杯茶的濃度和風味一致，更精確控制每批茶的品質，避免因大量沖泡而導致品質不穩定。", "C": "是雙江茶行的獨特作法。", "D": "文中並未提及中國醫藥大學有販售珍珠奶茶。"}, "psg": "", "need_img": false}, {"n": 12, "ans": "B", "stem": "「甚至連感冒發燒時，醫生總是建議：給她喝運動飲料。我不敢想像這些毒物如何毒害她們的身體。」有關作者對於運動飲料的看法，何者正確", "opts": [["A", "運動飲料可以排除身體中的毒素"], ["B", "運動飲料中含有的添加物可能對健康產生負面影響"], ["C", "運動飲料是感冒發燒時的唯一解藥"], ["D", "運動飲料是導致感冒發燒的根本原因"]], "exp": "(B)醫生建議給病人喝運動飲料可能的原因有補充水分和電解質，或於病人在身體虛弱或食慾不振時獲得一些簡單易消化的能量來維持身體活動。儘管如此，運動飲料並非是最佳的選擇，因為它們通常含有較高的糖分和其他添加物，若長期飲用可能對健康有負面影響。", "trans": "", "per": {"B": "醫生建議給病人喝運動飲料可能的原因有補充水分和電解質，或於病人在身體虛弱或食慾不振時獲得一些簡單易消化的能量來維持身體活動。儘管如此，運動飲料並非是最佳的選擇，因為它們通常含有較高的糖分和其他添加物，若長期飲用可能對健康有負面影響。"}, "psg": "", "need_img": false}, {"n": 13, "ans": "A", "stem": "「優質的珍珠奶茶，上面總是一層綿密的奶泡，同時表現茶香和奶香，兩者又能快樂的平衡。它取悅味蕾如同一場優美的舞蹈。」依據上文，茶香和奶香交互之間的影響可用下列何者形容", "opts": [["A", "相輔相成"], ["B", "脣亡齒寒"], ["C", "喧賓奪主"], ["D", "聊勝於無"]], "exp": "(A)本句旨在讚美珍珠奶茶獨特的味覺體驗，達到平衡與融合，品嚐時令人愉悅。相輔相成：互相輔助、配合，以完成某種事物。(B)嘴脣沒了，牙齒就會感到寒冷。比喻關係密切，休戚相關。(C)指客人的聲音比主人的還要大。比喻客人占了主人的地位或次要的事物侵占了原有主要的地位，反客為主。(D)比完全沒有略微好些。", "trans": "", "per": {"A": "本句旨在讚美珍珠奶茶獨特的味覺體驗，達到平衡與融合，品嚐時令人愉悅。相輔相成：互相輔助、配合，以完成某種事物。", "B": "嘴脣沒了，牙齒就會感到寒冷。比喻關係密切，休戚相關。", "C": "指客人的聲音比主人的還要大。比喻客人占了主人的地位或次要的事物侵占了原有主要的地位，反客為主。", "D": "比完全沒有略微好些。"}, "psg": "", "need_img": false}, {"n": 14, "ans": "C", "stem": "「香菇屬於木材腐朽菌，能利用木材與纖維質做為碳源。生長前期需葡萄糖、蔗糖活化酵素，後期則利用澱粉、纖維質與木質素。其氮源以有機氮與銨態氮為主，無法利用硝酸態氮，因此常添加米糠、玉米粉等有機氮。菌絲期適宜碳氮比為 25：1～40：1，子實體發育期則為 73：1，降低氮含量有助於出菇。此外，香菇適合 pH 值 4.5～6 的環境，pH 值 3.5～4.5 最利於原基形成與子實體發育。」依據上文，有關香菇營養需求與生長環境的說明，下列敘述何者最適當", "opts": [["A", "香菇可利用硝酸態氮做為氮素來源"], ["B", "香菇生長前期主要利用澱粉與木質素做為碳源"], ["C", "菌絲期的碳氮比若為 30：1 則適宜生長"], ["D", "香菇菌絲最適合生長於 pH 值 7.5 以上的環境"]], "exp": "(A)由「無法利用硝酸態氮」可知為非。(B)由「生長前期需葡萄糖、蔗糖」、「後期才利用澱粉、木質素」可知為非。(C)由「菌絲期適宜碳氮比為 25：1～40：1」可知正確。(D)由「適合 pH 值為4.5～6 的環境」可知為非。", "trans": "", "per": {"A": "由「無法利用硝酸態氮」可知為非。", "B": "由「生長前期需葡萄糖、蔗糖」、「後期才利用澱粉、木質素」可知為非。", "C": "由「菌絲期適宜碳氮比為 25：1～40：1」可知正確。", "D": "由「適合 pH 值為4.5～6 的環境」可知為非。"}, "psg": "", "need_img": false}, {"n": 15, "ans": "C", "stem": "焦桐從珍珠奶茶中的添加物，喚醒消費者對於食安問題的重視。關於「添加物」的敘述，何者正確", "opts": [["A", "市售奶茶多以人造奶精取代鮮乳，是為了提升營養成分"], ["B", "粉圓的彈牙口感主要來自熬煮技巧，與添加物的使用無關"], ["C", "香料、濃稠劑等添加物容易蒙蔽人們的味覺，反而無法分辨食物的原味"], ["D", "塑化劑常出現於一般飲料與食品當中，對人體有百益而無一害"]], "exp": "(A)以人造奶精取代鮮乳反而無助於提升營養成分。(B)粉圓的彈牙口感來自人工合成塑化劑等添加物，而非單純的熬煮技巧。(D)對人體有許多的毒害。", "trans": "", "per": {"A": "以人造奶精取代鮮乳反而無助於提升營養成分。", "B": "粉圓的彈牙口感來自人工合成塑化劑等添加物，而非單純的熬煮技巧。", "D": "對人體有許多的毒害。"}, "psg": "", "need_img": false}, {"n": 16, "ans": "A", "stem": "春水堂創辦人劉漢介曾說：「在人類的物質文明中，不管食衣住行，尤其是嗜好性物質這一區塊，品質是靈魂，沒有品質就產生不了嗜好！」下列何者最接近其「品質」的意涵", "opts": [["A", "奶茶須新鮮香醇，避免用奶精、糖精；粉圓的口感講究彈勁，不可黏稠，更不可摻加人工合成塑化劑"], ["B", "以廉價食材模擬了高級餐館的形式，再用相對較便宜的價格招徠不察的顧客"], ["C", "由於地瓜粉或木薯粉，都不能令粉圓產生彈牙的嚼感，大部分商家遂添加人工合成塑化劑"], ["D", "市售奶茶多含香料、增稠劑等添加物，也漸漸以人造奶精取代鮮乳，奶精含反式脂肪酸，奶味濃郁"]], "exp": "依據「品質是靈魂」可知劉漢介認為只有追求高品質，才能喚起人類對於事物真正的喜愛，因此選(A)說明珍珠奶茶製作過程中追求品質的表現。", "trans": "", "per": {"A": "依據「品質是靈魂」可知劉漢介認為只有追求高品質，才能喚起人類對於事物真正的喜愛，因此選(A)說明珍珠奶茶製作過程中追求品質的表現。"}, "psg": "", "need_img": false}, {"n": 17, "ans": "C", "stem": "有關〈珍珠奶茶〉的文句分析，對於①、②的研判應是：", "opts": [["A", "①、②皆正確"], ["B", "①、②皆錯誤"], ["C", "①正確，②錯誤"], ["D", "①錯誤，②正確"]], "exp": "(C)②文句中僅提及奶茶可以緩解因長期吃肉，維生素及無機鹽不足所導致的負面影響，非指全部的營養素。", "trans": "", "per": {"C": "②文句中僅提及奶茶可以緩解因長期吃肉，維生素及無機鹽不足所導致的負面影響，非指全部的營養素。"}, "psg": "　　①「當年文成公主下嫁松贊干布，帶去茶葉，傳授當地人烹茶技術，並用牛奶、羊奶熬煮茶葉」：奶茶的源起可能始於唐代。<br>　　②「北方的游牧民族長期吃肉，體內維生素和無機鹽不足，導致營養失調、消化不良；喝奶茶剛好可以緩解這些現象」：奶茶能補充體內所需的所有營養成分。", "need_img": false}, {"n": 18, "ans": "D", "stem": "翰林飲料店隆重開幕，特別邀請國文老師致贈題辭，下列何者最適合", "opts": [["A", "名山事業"], ["B", "民之喉舌"], ["C", "里仁為美"], ["D", "齒頰留香"]], "exp": "(A)書店。(B)報社。(C)賀遷居。", "trans": "", "per": {"A": "書店。", "B": "報社。", "C": "賀遷居。"}, "psg": "", "need_img": false}, {"n": 19, "ans": "C", "stem": "〈珍珠奶茶〉一文中提到飲食文化不僅影響烹飪與生活，也衍生出許多相關的慣用語。下列「 」內的飲食慣用語，何者使用最適當", "opts": [["A", "活動一開場便由主持人上臺「炒冷飯」活絡氣氛"], ["B", "他是這個地區的「落湯雞」，對周遭十分了解"], ["C", "表現不佳的他被公司「炒魷魚」，必須另尋職缺"], ["D", "他需要一針見血的「灌迷湯」才能透澈醒悟"]], "exp": "(A)比喻重複已做過的事或說過的話，沒有創新的內容。(B)比喻人渾身溼透或處於困境，十分狼狽。(C)比喻辭退、解僱。(D)恭維、奉承他人，使人心醉神迷。", "trans": "", "per": {"A": "比喻重複已做過的事或說過的話，沒有創新的內容。", "B": "比喻人渾身溼透或處於困境，十分狼狽。", "C": "比喻辭退、解僱。", "D": "恭維、奉承他人，使人心醉神迷。"}, "psg": "", "need_img": false}, {"n": 20, "ans": "D", "stem": "有關作家焦桐的敘述，下列何者正確", "opts": [["A", "著作以散文著名，兼及小說、戲劇、雜文。亦關心國文教育、環保"], ["B", "由聯合文學出版的散文集《第九味》是他著名的作品"], ["C", "自稱是「不可救藥的散文愛好者」，散文風格辭采華茂"], ["D", "成立「二魚文化」，創辦《飲食》雜誌，並主編年度飲食文選，為當代飲食文學的重要推手"]], "exp": "(A)指張曉風。(B)《第九味》是作家徐國能的作品。(C)指簡媜。", "trans": "", "per": {"A": "指張曉風。", "B": "《第九味》是作家徐國能的作品。", "C": "指簡媜。"}, "psg": "", "need_img": false}, {"n": 21, "ans": "B", "stem": "依據上文，愛玉和薜荔有什麼不同", "opts": [["A", "愛玉和薜荔是同一種植物，只是名稱不同"], ["B", "愛玉和薜荔在形態和細胞結構上有顯著差異"], ["C", "薜荔只生長在中海拔地區，愛玉則生長在低海拔"], ["D", "愛玉是由薜荔培育而來的"]], "exp": "文章中提到，愛玉和薜荔雖然同屬桑科榕屬，但它們在形態、細胞結構及生長環境上有顯著差異。薜荔主要生長於低海拔環境，而愛玉則是喜好中海拔的潮溼森林環境。", "trans": "", "per": {"B": "文章中提到，愛玉和薜荔雖然同屬桑科榕屬，但它們在形態、細胞結構及生長環境上有顯著差異。薜荔主要生長於低海拔環境，而愛玉則是喜好中海拔的潮溼森林環境。"}, "psg": "　　在嘉義文化夜市，一碗檸檬愛玉凍以微酸清新的滋味帶來夏日的舒適。愛玉是臺灣特有植物，生長於海拔 1200 至 1900 公尺的潮溼森林中，直到 19 世紀初才被發現並命名為 Ficus awkeotsang Makino。愛玉的製作繁瑣，需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍。天然愛玉柔嫩無可替代，而人工製品則略帶脆感。<br><br>　　愛玉與薜荔同屬桑科榕屬，但在形態、細胞結構與生長環境上差異明顯。薜荔適應低海拔環境，而愛玉喜好中海拔的潮溼森林。榕小蜂是愛玉的專屬授粉者，與愛玉樹形成精妙的依存關係。天然愛玉籽粒密實、色澤偏紅；人工栽培則籽粒稀疏、色澤偏黃。<br><br>　　愛玉是夏日解暑佳品，不耐高溫、冰涼滑嫩，與檸檬汁搭配最為經典。飲用時，冰涼的果凍猶如微風拂面，清新口感讓人回味無窮。品愛玉凍不僅是味覺享受，更象徵青春記憶與阿里山的自然之美。從森林的濃綠到日出的燦爛，每一碗愛玉凍都蘊含著自然的韻味與生命的清涼，讓人身心愉悅，感受大自然的溫柔和美好。<div class='aq-src'>（改寫自焦桐《蔬果歲時記．愛玉》）</div>", "need_img": false}, {"n": 22, "ans": "A", "stem": "依據上文，作者對愛玉凍的感受，下列敘述何者最適當", "opts": [["A", "愛玉凍是一種口感清新的甜點，讓人回憶起青春歲月和自然景象"], ["B", "愛玉凍是消暑解渴的必備食物，且耐高溫"], ["C", "愛玉凍象徵作者到阿里山遊玩的青春記憶"], ["D", "愛玉因製作過程簡單而成為夏日解暑聖品"]], "exp": "(A)作者在文中描述愛玉凍的清爽口感，並將其與青春回憶、阿里山的自然之美等聯繫在一起。(B)愛玉不耐高溫。(C)文中雖提到愛玉凍與阿里山自然美景相聯繫，但未直接表達作者個人的青春記憶，而是以普遍性的青春回憶與自然之美做為象徵。(D)由「愛玉的製作繁瑣，需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍」可知為非。", "trans": "", "per": {"A": "作者在文中描述愛玉凍的清爽口感，並將其與青春回憶、阿里山的自然之美等聯繫在一起。", "B": "愛玉不耐高溫。", "C": "文中雖提到愛玉凍與阿里山自然美景相聯繫，但未直接表達作者個人的青春記憶，而是以普遍性的青春回憶與自然之美做為象徵。", "D": "由「愛玉的製作繁瑣，需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍」可知為非。"}, "psg": "　　在嘉義文化夜市，一碗檸檬愛玉凍以微酸清新的滋味帶來夏日的舒適。愛玉是臺灣特有植物，生長於海拔 1200 至 1900 公尺的潮溼森林中，直到 19 世紀初才被發現並命名為 Ficus awkeotsang Makino。愛玉的製作繁瑣，需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍。天然愛玉柔嫩無可替代，而人工製品則略帶脆感。<br><br>　　愛玉與薜荔同屬桑科榕屬，但在形態、細胞結構與生長環境上差異明顯。薜荔適應低海拔環境，而愛玉喜好中海拔的潮溼森林。榕小蜂是愛玉的專屬授粉者，與愛玉樹形成精妙的依存關係。天然愛玉籽粒密實、色澤偏紅；人工栽培則籽粒稀疏、色澤偏黃。<br><br>　　愛玉是夏日解暑佳品，不耐高溫、冰涼滑嫩，與檸檬汁搭配最為經典。飲用時，冰涼的果凍猶如微風拂面，清新口感讓人回味無窮。品愛玉凍不僅是味覺享受，更象徵青春記憶與阿里山的自然之美。從森林的濃綠到日出的燦爛，每一碗愛玉凍都蘊含著自然的韻味與生命的清涼，讓人身心愉悅，感受大自然的溫柔和美好。<div class='aq-src'>（改寫自焦桐《蔬果歲時記．愛玉》）</div>", "need_img": false}, {"n": 23, "ans": "B", "stem": "文中愛玉的製作過程，哪一個步驟是為了提取果膠並製成愛玉凍", "opts": [["A", "晒乾後直接切片"], ["B", "用紗布袋浸泡並輕輕搓揉"], ["C", "剝去外皮並烘乾"], ["D", "用冷水反覆沖洗果肉"]], "exp": "(B)愛玉的製作需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍。", "trans": "", "per": {"B": "愛玉的製作需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍。"}, "psg": "　　在嘉義文化夜市，一碗檸檬愛玉凍以微酸清新的滋味帶來夏日的舒適。愛玉是臺灣特有植物，生長於海拔 1200 至 1900 公尺的潮溼森林中，直到 19 世紀初才被發現並命名為 Ficus awkeotsang Makino。愛玉的製作繁瑣，需將瘦果剖開、晒乾、浸水揉搓提取果膠，再靜置成凍。天然愛玉柔嫩無可替代，而人工製品則略帶脆感。<br><br>　　愛玉與薜荔同屬桑科榕屬，但在形態、細胞結構與生長環境上差異明顯。薜荔適應低海拔環境，而愛玉喜好中海拔的潮溼森林。榕小蜂是愛玉的專屬授粉者，與愛玉樹形成精妙的依存關係。天然愛玉籽粒密實、色澤偏紅；人工栽培則籽粒稀疏、色澤偏黃。<br><br>　　愛玉是夏日解暑佳品，不耐高溫、冰涼滑嫩，與檸檬汁搭配最為經典。飲用時，冰涼的果凍猶如微風拂面，清新口感讓人回味無窮。品愛玉凍不僅是味覺享受，更象徵青春記憶與阿里山的自然之美。從森林的濃綠到日出的燦爛，每一碗愛玉凍都蘊含著自然的韻味與生命的清涼，讓人身心愉悅，感受大自然的溫柔和美好。<div class='aq-src'>（改寫自焦桐《蔬果歲時記．愛玉》）</div>", "need_img": false, "appraise": "作者以細膩文字描繪愛玉凍的製作工藝與自然特性，展現其在臺灣夏日生活中的重要性。同時，將愛玉凍的冰涼口感與阿里山的森林景觀、青春回憶緊密相連，喚起對臺灣自然之美的情感聯繫。愛玉凍不僅是夏日解暑佳品，更象徵了自然的清新與生活的美好，營造出一種既具地方色彩又充滿情感的氛圍。"}, {"n": 24, "ans": "B", "stem": "依據上文，□□□□內最有可能為下列何者", "opts": [["A", "碳酸飲料"], ["B", "茶類飲料"], ["C", "咖啡飲料"], ["D", "運動飲料"]], "exp": "(B)茶類飲料主要占比 33％，因此為非酒精飲料業產值創新高的主要推手。", "trans": "", "per": {"B": "茶類飲料主要占比 33％，因此為非酒精飲料業產值創新高的主要推手。"}, "psg": "　　經濟部發布我國非酒精飲料業產值統計，自 2015 年起產值連續 8 年正成長，而 2022 年產值更高達 570 億元創歷史新高，年增3.8％。依據行政院主計總處行業統計分類定義，非酒精飲料業是指從事含酒精成分不超過 0.5％飲料製造行業，其內容大致可分為茶類飲料、運動飲料、礦泉水、碳酸飲料、果蔬汁、咖啡飲料、其他非酒精飲料等產品。若以產品面觀察，□□□□為非酒精飲料業 2022 年產值創新高的最大推手（如右圖所示）。<br><br>　　以茶類飲料為例，為了打破中老年人泡茶品茗的刻板印象，國內廠商研發出風味多樣且方便飲用的包裝茶飲，透過大膽創新的廣告推銷，快速推升茶類飲料之產值。然而隨著泡沫紅茶店、手搖飲品的崛起，瓜分了消費市場，以致茶類飲料產值自 1995起連續 6 年大幅下滑，但在業者不斷開發新品及促銷下，產值慢慢回升，雖然未能重回 200 億元水準的榮光時期，但占比卻始終居冠。<br><br>　　我國非酒精飲料業產值在 2023 年 1 至 7 月累積已達 335 億元，年增 3.6％，在業者持續推出新品及各種促銷活動的帶動下，今年全年產值可望延續近 8 年的成長態勢，再創歷史新高紀錄。<div class='aq-src'>（改寫自經濟部《經新聞 2023/10/16》）</div>", "need_img": false, "imgs": [["", "img/珍珠奶茶/d576245ecf9cb6f8.png"]]}, {"n": 25, "ans": "C", "stem": "某廣告公司接受委託，要為一家手搖飲店的產品設計廣告詞，下列何者最適當", "opts": [["A", "白日衣衫淨"], ["B", "姑蘇城外韓三食"], ["C", "茗悅幾時有"], ["D", "清粥已過萬重山"]], "exp": "此處引用諧音句法。(A)諧音「白日依山盡」，為洗衣店。(B)諧音「姑蘇城外寒山寺」，為韓國料理店。(C)諧音「明月幾時有」，為茶飲店。(D)諧音「輕舟已過萬重山」，為粥麵店。", "trans": "", "per": {"A": "諧音「白日依山盡」，為洗衣店。", "B": "諧音「姑蘇城外寒山寺」，為韓國料理店。", "C": "諧音「明月幾時有」，為茶飲店。", "D": "諧音「輕舟已過萬重山」，為粥麵店。"}, "psg": "　　經濟部發布我國非酒精飲料業產值統計，自 2015 年起產值連續 8 年正成長，而 2022 年產值更高達 570 億元創歷史新高，年增3.8％。依據行政院主計總處行業統計分類定義，非酒精飲料業是指從事含酒精成分不超過 0.5％飲料製造行業，其內容大致可分為茶類飲料、運動飲料、礦泉水、碳酸飲料、果蔬汁、咖啡飲料、其他非酒精飲料等產品。若以產品面觀察，□□□□為非酒精飲料業 2022 年產值創新高的最大推手（如右圖所示）。<br><br>　　以茶類飲料為例，為了打破中老年人泡茶品茗的刻板印象，國內廠商研發出風味多樣且方便飲用的包裝茶飲，透過大膽創新的廣告推銷，快速推升茶類飲料之產值。然而隨著泡沫紅茶店、手搖飲品的崛起，瓜分了消費市場，以致茶類飲料產值自 1995起連續 6 年大幅下滑，但在業者不斷開發新品及促銷下，產值慢慢回升，雖然未能重回 200 億元水準的榮光時期，但占比卻始終居冠。<br><br>　　我國非酒精飲料業產值在 2023 年 1 至 7 月累積已達 335 億元，年增 3.6％，在業者持續推出新品及各種促銷活動的帶動下，今年全年產值可望延續近 8 年的成長態勢，再創歷史新高紀錄。<div class='aq-src'>（改寫自經濟部《經新聞 2023/10/16》）</div>", "need_img": false, "imgs": [["", "img/珍珠奶茶/d576245ecf9cb6f8.png"]]}, {"n": 26, "ans": "D", "stem": "本文提到我國非酒精飲料業自 2015 年起產值連續成長，並透過數據與範例說明各類產品的發展情況。下列敘述何者最適當", "opts": [["A", "我國非酒精飲料業產值自 2015 年起連續 8 年正成長，2023 年也已經超越去年的產值"], ["B", "根據圖表所示，我國非酒精飲料主要產品以運動飲料和咖啡飲料的占比最低"], ["C", "茶類飲料的產值曾經隨著手搖飲品的崛起，以及工廠外移東南亞的因素而短暫下滑"], ["D", "國內廠商透過研發風味多樣且方便飲用的包裝茶飲，並搭配創新的廣告行銷，推升茶類飲料的產值"]], "exp": "(A)2023 年尚未結束，因此產值只能說「可望」超越，並非「已經」超越。(B)運動飲料和礦泉水同為 5.4％，占比最低。(C)文中並未提及工廠外移東南亞的因素。", "trans": "", "per": {"A": "2023 年尚未結束，因此產值只能說「可望」超越，並非「已經」超越。", "B": "運動飲料和礦泉水同為 5.4％，占比最低。", "C": "文中並未提及工廠外移東南亞的因素。"}, "psg": "　　經濟部發布我國非酒精飲料業產值統計，自 2015 年起產值連續 8 年正成長，而 2022 年產值更高達 570 億元創歷史新高，年增3.8％。依據行政院主計總處行業統計分類定義，非酒精飲料業是指從事含酒精成分不超過 0.5％飲料製造行業，其內容大致可分為茶類飲料、運動飲料、礦泉水、碳酸飲料、果蔬汁、咖啡飲料、其他非酒精飲料等產品。若以產品面觀察，□□□□為非酒精飲料業 2022 年產值創新高的最大推手（如右圖所示）。<br><br>　　以茶類飲料為例，為了打破中老年人泡茶品茗的刻板印象，國內廠商研發出風味多樣且方便飲用的包裝茶飲，透過大膽創新的廣告推銷，快速推升茶類飲料之產值。然而隨著泡沫紅茶店、手搖飲品的崛起，瓜分了消費市場，以致茶類飲料產值自 1995起連續 6 年大幅下滑，但在業者不斷開發新品及促銷下，產值慢慢回升，雖然未能重回 200 億元水準的榮光時期，但占比卻始終居冠。<br><br>　　我國非酒精飲料業產值在 2023 年 1 至 7 月累積已達 335 億元，年增 3.6％，在業者持續推出新品及各種促銷活動的帶動下，今年全年產值可望延續近 8 年的成長態勢，再創歷史新高紀錄。<div class='aq-src'>（改寫自經濟部《經新聞 2023/10/16》）</div>", "need_img": false, "appraise": "本報導調查自 2015 年到 2023 年的全國非酒精飲料業的產值變化，分析我國在非酒精飲料產業值的成長曲線以及各主要產品的產值占比，以提供各廠商進行產品研發、推銷的重要參考。", "imgs": [["", "img/珍珠奶茶/d576245ecf9cb6f8.png"]]}], "workbook": {"title": "習作Ａ　第四課　珍珠奶茶", "sections": [{"kind": "table", "head": "壹 基礎認知站　一、字音探勘隊（每題 1 分，共 8 分）", "cols": ["", "字音", "詞語", "", "字音", "詞語"], "rows": [["1", "ㄔㄢ", "「摻」入", "2", "ㄕㄢ", "解腥去「膻」"], ["3", "ㄧㄢˊ", "「筵」席", "4", "ㄊㄧㄢˊ", "和「闐」玉"], ["5", "ㄐㄩㄥˇ", "「迥」異", "6", "ㄙㄨˋ", "「塑」化劑"], ["7", "ㄌㄟˇ", "味「蕾」", "8", "ㄕㄨㄣˇ", "吸「吮」"]]}, {"kind": "table", "head": "二、字形領航員（每題 1 分，共 8 分）", "cols": ["", "字形", "詞語", "", "字形", "詞語"], "rows": [["1", "搓", "「ㄘㄨㄛ」湯圓", "2", "烹", "「ㄆㄥ」茶方式"], ["3", "醇", "香「ㄔㄨㄣˊ」", "4", "稟", "天賦異「ㄅㄧㄥˇ」"], ["5", "狡", "「ㄐㄧㄠˇ」猾", "6", "罔", "「ㄨㄤˇ」顧後果"], ["7", "瑕", "完美無「ㄒㄧㄚˊ」", "8", "徜", "「ㄔㄤˊ」徉"]]}, {"kind": "table", "head": "三、字義飛行傘（每題 2 分，共 8 分）", "cols": ["", "詞語", "答案", "", "詞語", "答案"], "rows": [["1", "推本「溯」源", "C", "2", "雕「塑」", "D"], ["3", "「朔」日", "B", "4", "「朔」風", "A"]], "note": "請選出下列「　」內的正確字義代號。<br>參考選項：A北方的　B農曆每月初一日　C往上或往前推求、回想　D用泥土等做成人、物的形狀"}, {"kind": "table", "head": "四、文學常識解碼（每格 2 分，共 6 分）", "cols": ["項目", "內容"], "rows": [["寫作歷程", "1 早年從事報紙、雜誌的編輯工作。在《完全壯陽食譜》詩集出版後，展現對（1 <b>飲食文學</b>）的深厚興趣並著力推廣，後來成立「二魚文化」，創辦《飲食》雜誌<br>2 近年來更關注（2 <b>食安問題</b>），強調健康的飲食觀念，重視下一代飲食文化的教育"], ["寫作風格", "詩作題材多元，意象鮮明，善用（3 <b>戲謔手法</b>）嘲諷政治；散文藉自身飲食經驗，書寫食後感懷與賞評，探索社會議題及人生況味，充滿人文情懷"], ["作品", "1 詩集《完全壯陽食譜》、《青春標本》、《焦桐詩集：1980～1993》等<br>2 散文集《暴食江湖》、《臺灣肚皮》、《味道福爾摩莎》、《慢食天下》等"]], "note": "請依據你對焦桐的認識，完成下列表格（　）中的內容。"}, {"kind": "quiz", "head": "五、綜合理解練習（每題 5 分，共 40 分）", "items": [{"n": 1, "q": "下列各組「　」內的字，何者讀音相同？", "ans": "C", "opts": [["A", "連「袂」／「訣」竅", "ㄇㄟˋ／ㄐㄩㄝˊ。"], ["B", "「徜」徉／流「淌」", "ㄔㄤˊ／ㄊㄤˇ。"], ["C", "「筵」席／蜿「蜒」", "ㄧㄢˊ。"], ["D", "「篩」網／「薛」寶釵", "ㄕㄞ／ㄒㄩㄝ。"]]}, {"n": 2, "q": "下列文句，何者有錯別字？", "ans": "D", "opts": [["A", "奸商在法庭上向法官如實稟告犯下的罪刑", ""], ["B", "兩篇文章筆法風格迥異，應是不同人所寫", ""], ["C", "此作案手法罔顧人倫情理，絲毫沒有人性", ""], ["D", "遠赴他鄉的遊子，念滋在滋的只有家鄉味", "念「茲」在「茲」。"]]}, {"n": 3, "q": "焦桐在〈珍珠奶茶〉一文中寫到不肖業者在飲料、食品中摻入塑化劑，並對此多有批評。如此關心社會的行為，可以用下列哪個成語形容？", "ans": "B", "opts": [["A", "懸壺濟世", "行醫救人。"], ["B", "人飢己飢", "形容人具有慈悲仁愛的胸懷。"], ["C", "造福桑梓", "用於祝賀人競選獲勝的賀辭。"], ["D", "敝帚自珍", "比喻東西雖不好，卻因為是自己所擁有，故非常珍視。"]]}, {"n": 4, "q": "描述一件事物時，轉變其原來性質，故意把物當做人、把人當做物，或者把抽象事物當做具體事物來描寫，這種修辭格稱為「轉化」。下列何者使用轉化修辭？", "ans": "A", "opts": [["A", "粉圓徜徉在茶湯中，吸吮入嘴，輕柔撫觸舌尖，滑動", "由「徜徉」、「撫觸」是人做出的動作，可知為「轉化」中的擬人化。"], ["B", "我不在乎誰發明了珍珠奶茶，只在乎誰認真泡茶？在乎誰老老實實製作", "懸問。"], ["C", "我愛看業者用雪克器搖茶，動作瀟灑帥氣，帶著表演性質，總覺得像一種舞蹈", "明喻。"], ["D", "據說他們愛死了這種清香美味的奶茶，已經到了「寧可三日無糧，不可一日無茶」的地步", "引用。"]]}, {"n": 5, "q": "「當年文成公主下嫁松贊干布，帶去茶葉，傳授當地人烹茶技術，並用牛奶、羊奶熬煮茶葉，據說他們愛死了這種清香美味的奶茶，已經到了『寧可三日無糧，不可一日無茶』的地步。不僅美味，其中還存在著養生的道理。中醫觀點認為奶茶能解腥去膻、清內熱。北方的游牧民族長期吃肉，體內維生素和無機鹽不足，導致營養失調、消化不良；喝奶茶剛好可以緩解這些現象。」關於上文，下列推論何者正確？", "ans": "C", "opts": [["A", "松贊干布喜愛文成公主帶去的茶葉", "文中未提到。"], ["B", "遊牧民族種茶葉取代糧食導致糧荒", "文中未提到。"], ["C", "遊牧民族會透過喝奶茶補充維生素", ""], ["D", "此奶茶能根治營養失調和消化不良", "僅能「緩解」，無「根治」。"]]}, {"n": 6, "q": "「網友有時會罵頂級餐館賣得太貴，其實應該考慮的是合理與否；頂級餐館的獲利，往往遠不如一般連鎖餐館。形式是最容易模仿的，低級餐館往往以廉價食材模擬了高級餐館的形式，再用相對較便宜的價格招徠不察的顧客；同樣是供應套餐，都有沙拉、前菜、湯、主菜、甜點、飲料，各家餐館呈現的每一種食材、每一個細節卻都存在著極大的落差。」關於上文，下列推論何者正確？", "ans": "C", "opts": [["A", "作者認為價格的高低才是餐館頂級與否的依據", "無此敘述，應是建議消費者思考「價格和其供應的食材品質是否合理」。"], ["B", "頂級餐館的餐點和獲利往往不如一般連鎖餐館", "不包含餐點。"], ["C", "低級餐館會供應套餐但以不高的價格吸引顧客", ""], ["D", "頂級餐館提供的食材和細節均一致，沒有落差", "無此敘述，而是認為「各家餐館皆有落差」。"]]}, {"n": 7, "q": "〈珍珠奶茶〉一文提及：「我在上海、澳門看到臺灣的珍珠奶茶也大受歡迎，忽然升起榮耀感，一種奇怪的認同感。如今珍珠奶茶已風行亞洲、歐洲、美國甚至中東國家；倫敦蘇活區（SOHO）珍珠奶茶店“Bubbleology”生意興隆，其原料、包裝都來自臺灣。」下列哪則新聞標題最有可能也讓作者升起「榮耀感」？", "ans": "B", "opts": [["A", "國際教育有成，尼加拉瓜走入中臺灣", ""], ["B", "穿夾腳拖跑完地表最長超馬，臺灣製造拖鞋夯國際", "題幹旨為珍珠奶茶風靡國際而引起作者榮耀感，必須符合臺灣特色、走入國際的條件，可知(B)最符合。"], ["C", "16 條路線踩點 GO！盼民眾走出戶外自行車遊臺灣", ""], ["D", "東南亞特色融入臺灣傳統習俗，年貨大街包粽吹起異國風", ""]]}, {"n": 8, "q": "聞名世界的《小王子》一書中，小王子深愛他的玫瑰花，因此狐狸對小王子說：「你為你的玫瑰花所花費的時間，使你的玫瑰花變得重要。」這段話所傳達的理念最貼近〈珍珠奶茶〉的哪句話？", "ans": "D", "opts": [["A", "吾人學習飲食之道，無非是學習知味辨味，理解食物及其操作", ""], ["B", "我在上海、澳門看到臺灣的珍珠奶茶也大受歡迎，忽然升起榮耀感，一種奇怪的認同感", ""], ["C", "像習慣欺瞞的人不會講出真誠的話，當味覺被香料和增稠劑欺瞞慣了，就再也難以接受誠懇而美好的味道", ""], ["D", "用化學藥劑促長的香菇，3 個月即可收成；以自然農耕法培育的香菇需費時 12 個月才能收成，它們的價格豈能一樣", "題幹文句在於強調為在乎的事物付出心力的重要，與〈珍珠奶茶〉中作者不贊同使用化學藥劑促長香菇，從而提高生產效率和降低成本的作法，認為自然農耕法種植的香菇，其風味、營養、安全更有價值的理念最貼近。"]]}]}, {"kind": "read", "head": "貳 進階實力站　一、閱讀測驗（每題 3 分，共 18 分）(一)", "passage": "　　粥飯二物，為家常日用之需，其中機彀，無人不曉，焉用越俎者強為致詞？然有吃緊二語，巧婦知之而不能言者，不妨代為喝破，使姑傳之媳，母傳之女，以兩言代千百言，亦簡便利人之事也。<br><br>　　先就粗者言之。飯之大病，在內生外熟，非爛即焦；粥之大病，在上清下澱<sup>①</sup>，如糊如膏。此火候不均之故，惟最拙最笨者有之，稍能炊爨<sup>②</sup>者，必無是事。然亦有剛柔合道，燥溼得宜，而令人咀和嚼之，有粥飯之美形，無飲食之至味者。<br><br>　　其病何在？曰：「挹<sup>③</sup>水無度，增減不常之為害也。」其吃緊二語，則曰：「粥水忌增，飯水忌減。」米用幾何，則水用幾何，宜有一定之度數。如醫人用藥，水一盅或盅半，煎至七分或八分，皆有定數。若以意為增減，則非藥味不出，即藥性不存，而服之無效矣。不善於執爨者，用水不均，煮粥常患其少，煮飯常苦其多。<div class='aq-src'>註：①澱：沉澱。②爨：音ㄘㄨㄢˋ，以火燒煮食物。③挹：音ㄧˋ，舀取。</div><div class='aq-src'>（節錄自李漁《閒情偶寄．飲饌部．穀食第二》）</div><details style='margin-top:10px'><summary>語譯</summary>　　粥和飯這兩樣東西，是家庭平日生活的必需食物，做飯的原理誰都知道，還用我多費言辭嗎？但是有要緊的兩句話，巧媳婦雖然知道卻說不出來，我不妨代她們講出來，將來婆婆教給媳婦，母親傳給女兒，以兩句話替代千言萬語，也是一件簡便利人的事情。<br>　　第一句話先從粗略的方面來講。煮飯的大問題，在內生外熟，不是爛就是焦；煮粥的大問題，在於米沉在下面，上面只有清湯，像漿糊一樣。這是火候不夠均衡的原因，只有最笨拙的人才會有的，稍微能做飯的人，一定沒有這種事。但也有煮的飯軟硬合宜，粥乾溼適中，而人咀嚼它，雖看著好看，吃起來卻沒有味道。<br>　　那麼問題在哪裡？說：「在於沒有節制的用水，增減沒有根據規律。」要緊的第二句話，則是說：「煮粥時水忌增加，煮飯時水忌減少。」米用多少，水就用多少，應該有一個確定的標準。像是醫生使用藥物，一盅水還是一盅半，煎至七分或八分，都有定數。如果隨意增減，那要不是藥的味道出不來，就是藥的功用不存在，而服用就沒有效果了。不擅長做飯的人，用水不固定，煮粥常擔心水太少，煮飯常常苦於水太多。</details>", "items": [{"n": 1, "q": "依據本文，關於粥飯的敘述，下列何者正確？", "ans": "C", "opts": [["A", "粥之美形應是上清下澱且如膏糊狀的粥", "粥之美形應是米粒剛柔合道，燥溼得宜。"], ["B", "火候掌控不好，粥會有燥溼得宜的情況", "火候掌控不好會使粥上清下澱，如膏糊狀。"], ["C", "煮粥時水不宜增加太多，煮飯時不宜太少", ""], ["D", "煮飯時如果加水沒有定數，就會喪失藥性", "飯實際上沒有藥性，作者僅是以煎藥方式來比喻。"]]}, {"n": 2, "q": "關於本文的寫作手法，下列敘述何者正確？", "ans": "B", "opts": [["A", "作者詳述不同的粥品有不同的煮粥方法", "本文未提到不同粥品的煮粥方式。"], ["B", "本文以煎藥方式來比喻煮粥的水量多寡", ""], ["C", "先總說煮飯時的忌諱再分說吃米的好處", "先總說煮飯時的問題再分說煮飯的忌諱。"], ["D", "第三段以激問的方式開頭引起讀者興趣", "以提問（自問自答）方式。"]]}, {"n": 3, "q": "依據本文對於煮飯時米量和水量的要求，下列哪張圖片的紀錄結果最接近？<img src='img/珍珠奶茶/2935e5ebe63b267b.png' style='max-width:100%;display:block;margin:10px auto;width:520px' alt=''>", "ans": "A", "opts": [["A", "（見上圖）", "本文提及「米用幾何，則水用幾何」，可知米量越多，水量應越多。"], ["B", "（見上圖）", ""], ["C", "（見上圖）", ""], ["D", "（見上圖）", ""]]}]}, {"kind": "read", "head": "一、閱讀測驗 (二)", "appraise": "本文節錄自「連鎖飲料便利商店及速食業之現場調製飲料標示規定」之修正公文。", "passage": "主旨：修正「連鎖飲料便利商店及速食業之現場調製飲料標示規定」，並自中華民國 112 年 1 月 1 日生效。<br>正文：<br>一、本規定依《食品安全衛生管理法》第二十五條第二項規定訂定之。<br>二、具稅籍登記之連鎖飲料業、連鎖便利商店業及連鎖速食業（以下簡稱為連鎖業者）之現場調製飲料，應依本規定辦理標示。<br>三、前點所稱之連鎖業者，指公司或商業登記上使用相同之名義，或經由加盟、授權等方式使用相同名義者。<br>四、……含咖啡因成分之現場調製飲料，應標示該杯飲料總咖啡因含量之最高值，並加註「最高值」；否則應以紅黃綠標示區分總咖啡因含量，該標示得以符號或圖樣標示之：<br>（一）紅色代表每杯之總咖啡因含量二百零一毫克以上。<br>（二）黃色代表每杯之總咖啡因含量一百零一毫克至二百毫克。<br>（三）綠色代表每杯之總咖啡因含量一百毫克以下。<br>五、添加茶、咖啡，或以果蔬為品名之飲料，應依下列規定標示：<br>（一）添加茶或以茶香料調製之飲料：<br>1 以茶葉、茶粉、茶湯、茶湯之濃縮液，或以天然茶葉製得之原料調製者，應標示茶葉原料來源之原產地（國）。如茶葉原料混合二個以上產地（國）者，應依其含量多寡由高至低標示之。<br>2 不含茶葉、茶粉、茶湯、茶湯之濃縮液，或以天然茶葉製得之原料，僅以茶香料調製者，應於品名標示「○○風味」或「○○口味」字樣。<br>（二）添加咖啡之飲料：<br>咖啡原料來源之原產地（國）。若咖啡原料混合二個以上產地（國）者，應依其含量多寡由高至低標示之。<br>（三）以果蔬為品名之飲料：<br>1 果蔬汁含量應達百分之十以上，始得以「○○汁」為品名。<br>2 果蔬汁含量未達百分之十者，品名應標示為「○○飲料」或等同意義字樣。<br>3 未含果蔬汁者，應於品名標示「○○風味」或「○○口味」字樣。<div class='aq-src'>（節錄自衛授食字第 1111300624 號）</div>", "items": [{"n": 4, "q": "依據上文規定，若小翰想創業開設連鎖飲料店，關於①、②的研判應是：<br>①小翰的店必須依照《食品安全衛生管理法》的規範。<br>②小翰創業前須得到該連鎖業者的加盟或授權等方式。", "ans": "A", "opts": [["A", "①、②皆正確", ""], ["B", "①、②皆錯誤", ""], ["C", "①正確，②錯誤", ""], ["D", "①錯誤，②正確", ""]]}, {"n": 5, "q": "過量的咖啡因對人類來說也會產生危害，因此產品必須明示咖啡因的含量。下列哪個產品標示符合上文要求？<img src='img/珍珠奶茶/57b6fc7c20459447.png' style='max-width:100%;display:block;margin:10px auto;width:560px' alt=''>", "ans": "B", "opts": [["A", "（見上圖）", "應標示為紅色。"], ["B", "（見上圖）", "正文第四點說明應標示總咖啡因含量之最高值，並加註「最高值」，否則應以紅黃綠標示區分。"], ["C", "（見上圖）", "應標示紅色，或是將說明改為「咖啡因最高值」。"], ["D", "（見上圖）", "應標示為綠色。"]]}, {"n": 6, "q": "依據上文規定，右圖飲料的產品標示有何問題？<img src='img/珍珠奶茶/b5cc4f2569243023.png' style='max-width:100%;display:block;margin:10px auto;width:320px' alt=''>", "ans": "A", "opts": [["A", "品名應標示為「檸檬風味紅茶」", "成分中未含檸檬果汁，標示應更正為「檸檬風味紅茶」。"], ["B", "成分不含檸檬汁依規定無法販售", ""], ["C", "成分中的印度和越南應調換順序", ""], ["D", "無咖啡原料不必標示咖啡因總量", ""]]}]}, {"kind": "table", "head": "二、趣味文學體驗（每題 3 分，共 12 分）", "cols": ["", "文句", "答案", "成語說明"], "rows": [["1", "相傳燧人氏教民鑽木取火，結束了原始人類□□□□的生活。", "B", "茹毛飲血：上古時候，人們尚不知用火，連毛帶血生食鳥獸。"], ["2", "他為了解決一時困難而向地下錢莊借貸，那無異是在□□□□。", "A", "飲鴆止渴：比喻只求解救眼前困難，而不顧將來的大禍患。"], ["3", "他知足常樂，每天過著□□□□的生活就滿足了。", "D", "簞食瓢飲：比喻安貧樂道。"], ["4", "獨自在外環島旅行的生活，可能需要□□□□，和住在家裡的生活有很大的落差。", "C", "餐風飲露：形容野外生活或行旅的艱苦。"]], "note": "「飲」人注意：請閱讀下列文句，填入與「飲」有關的成語代號。<br>參考選項：A飲鴆止渴　B茹毛飲血　C餐風飲露　D簞食瓢飲"}, {"kind": "table", "head": "參 挑戰加分站（不計分）", "cols": ["", "短文", "答案", "說明"], "rows": [["1", "1886 年，藥劑師彭伯頓創造一種風味糖漿，並將糖漿與汽水混合後，創造了這種口味獨特、可以在冷飲櫃出售的碳酸飲料，一開始每天賣不到 10 瓶。但今天，這一項飲料成為世界上最有價值的商標之一。", "C", "由「汽水」、「碳酸飲料」、「最有價值的商標之一」可知。"], ["2", "這是一種□□豆在經過烘焙磨粉後通過沖泡製成的飲料，是世界上流行範圍最廣泛的飲料之一。人們通常會為了提振精神，或在用餐、社交和閱讀時飲用。這種飲料的原料原產於東非衣索比亞，現多栽培於熱帶地區。", "A", "由「經過烘焙磨粉」、「提振精神」、「原料……現多栽培於熱帶地區」可知。"], ["3", "□□是經過採摘、萎凋、揉捻、發酵、乾燥等步驟生產出來的，沖泡方式包含熱泡及冷泡，飲品顏色呈深紅色、香氣撲鼻。主要產地有中國、斯里蘭卡、印度阿薩姆邦、肯亞等。臺灣的著名品種包括「阿里山□□」或「日月潭□□」。", "B", "由生產步驟經過「揉捻（茶葉）」、「沖泡方式包含熱泡及冷泡」、產地可知。"]], "note": "飲水思源：閱讀短文內容，思考分別是介紹何種飲料的描述，填入適當的代號。<br>參考選項：A咖啡　B紅茶　C可樂"}]}, "advQ": [{"kind": "table", "head": "二、進階練習", "cols": ["", "詞彙意義", "答案"], "rows": [["1", "指世故圓滑的人。", "<span class='wk-a'>E</span>"], ["2", "有生活保障的工作。", "<span class='wk-a'>G</span>"], ["3", "表示遭到拒絕不受歡迎。", "<span class='wk-a'>H</span>"], ["4", "把不同的事物彙集在一起。", "<span class='wk-a'>F</span>"], ["5", "指無辜，背負不好的名聲和罪名。", "<span class='wk-a'>D</span>"], ["6", "比喻人渾身溼透或處於困境，十分狼狽。", "<span class='wk-a'>A</span>"], ["7", "用甜言蜜語恭維、奉承他人，使人心醉神迷。", "<span class='wk-a'>C</span>"], ["8", "比喻重複已做過的事或說過的話，沒有創新的內容。", "<span class='wk-a'>B</span>"]], "note": "飲食文化衍生出許多有趣的詞彙，請將下列選項中的詞彙填入適當的（　）中。<br>參考選項：(A)落湯雞　(B)炒冷飯　(C)灌迷湯　(D)背黑鍋　(E)老油條　(F)大雜燴　(G)鐵飯碗　(H)閉門羹"}], "basicQ": [{"n": 1, "q": "下列文句，何者有錯別字？", "ans": "C", "opts": [["A", "在玉米濃湯裡摻入一些胡椒粉，味道會更鮮美", ""], ["B", "他總是喜歡一個人無憂無慮的徜徉在青山綠水間", ""], ["C", "這只乾隆皇帝的奶茶碗，使用完美無暇的和闐玉製作", "暇→瑕。"], ["D", "珠寶工藝師將鑽石嵌入戒臺，完成這只價值不菲的鑽戒", ""]]}, {"n": 2, "q": "下列有關〈珍珠奶茶〉一文的敘述，何者正確？", "ans": "C", "opts": [["A", "作者認為頂級餐館的獲利一定低於連鎖餐館", "文中僅提及「往往不如一般連鎖餐館」，無法得知是否一定低於連鎖餐館。"], ["B", "臺南的「翰林茶館」是珍珠奶茶正宗的發源店", "臺中「春水堂」、臺南「翰林茶館」皆說自己是珍珠奶茶的發源店，可惜這兩家店當初都未申請專利。"], ["C", "珍珠奶茶的美感來自於它的外觀和口感的完美結合，形成一種獨特的飲品", ""], ["D", "雖然用化學藥劑促長與自然農耕法培育的香菇價格不同，但在營養和風味上完全相同", "在營養和風味上也迥異。"]]}, {"n": 3, "q": "閱讀下文，有關作者對塑化劑事件的看法，何者敘述最適當？<div class='aq-sub'>　　許多食品加工業者、餐館為了追求最大利潤，罔顧後果的降低成本，竟在飲料、食品中摻入塑化劑。新聞爆發後，我憤怒難抑，鬱悶難紓。我的長女今年 24 歲，她已經吃了 24 年的塑化劑；我的么女今年 12 歲，她吃了 12 年的塑化劑。甚至連感冒發燒時，醫生總是建議：給她喝運動飲料。我不敢想像這些毒物如何毒害她們的身體。<br>　　黑心商人的事業越做越大，我們的健康越來越糟。</div>", "ans": "D", "opts": [["A", "對於黑心商人的事業越做越大不置可否", ""], ["B", "贊同醫生對於病人可補充運動飲料的建議", ""], ["C", "食品加工業者添加塑化劑是為了縮短食品製程", ""], ["D", "將食品安全問題個人化，以彰顯問題的嚴重性", "作者提及自己的兩個女兒是為了將食品安全問題個人化，讓讀者更能夠感同身受，加深對問題的認識。"]]}, {"n": 4, "q": "依據〈珍珠奶茶〉一文，下列①、②文意解說的研判應是：<br>①「當味覺被香料和增稠劑欺瞞慣了，就再也難以接受誠懇而美好的味道」：食品加工業者過度依賴人工添加物，導致消費者難接受純粹自然的食物。<br>②「用化學藥劑促長的香菇，3 個月即可收成；以自然農耕法培育的香菇需費時 12 個月才能收成」：兩種栽種香菇的方式反映消費者不願意花過長的時間等待收成。", "ans": "C", "opts": [["A", "①、②皆正確", ""], ["B", "①、②皆錯誤", ""], ["C", "①正確，②錯誤", "②兩種栽種香菇的方式反映自然農耕法需要更多的時間和成本，但對人體的安全與健康較好。與消費者是否願意等待無關。"], ["D", "①錯誤，②正確", ""]]}, {"n": 5, "q": "根據文意，何者為(甲)、(乙)二文均提及的內容？<div class='aq-sub'>(甲)　我不在乎誰發明了珍珠奶茶，只在乎誰認真泡茶？在乎誰老老實實製作？由於地瓜粉或木薯粉，都不能令粉圓產生彈牙的嚼感，大部分商家遂添加人工合成塑化劑。<br>　　市售奶茶多含香料、增稠劑等添加物，也漸漸以人造奶精取代鮮乳，奶精含反式脂肪酸，奶味濃郁；那是一種娛樂食物。娛樂食物多含高熱量、高脂肪、高鹽，這種東西很狡猾，從不呈現食物的原味，念茲在茲僅僅是要添加什麼，以全方位滿足人們味覺的快感。<br>(乙)　超市賣的花生油裡沒有花生／辣椒油裡從來也不見辣椒／橄欖油裡當然也不會有橄欖／就像太陽餅裡沒有太陽／老婆餅裡沒有老婆一樣自然／你必須習慣，因為／你住的地方叫福爾謀殺／　人們的肚裡撐飽著劣質米／裝滿香精色素塑化劑銅葉綠素／皮肉吸收過剩的成長激素／外星人正在基因改造同胞／經過 CNS 國家標準認證的新新人類／百毒不侵的生化人種／名為：新台灣人<div class='aq-src'>（劉正偉〈新台灣人——記假油事件〉）</div></div>", "ans": "A", "opts": [["A", "令人憂心的食安問題", "(甲)文「大部分商家遂添加人工合成塑化劑」、「市售奶茶多含香料、增稠劑等添加物」、「人造奶精取代鮮乳」；(乙)文篇名「記假油事件」，文中「裝滿香精色素塑化劑銅葉綠素」、「成長激素」、「基因改造」可知均提及令人憂心的食安問題。"], ["B", "新臺灣人都喜歡吃娛樂食物", "(甲)文僅提及市售添加物的奶茶是一種娛樂食物，能滿足人們味覺的快感；(乙)文並未提及。"], ["C", "多元的飲食選擇提供更多營養來源", "(甲)、(乙)文均未提及。"], ["D", "新世代臺灣人的消費能力越來越好", "(甲)、(乙)文均未提及。"]]}, {"n": 6, "q": "「譬喻」修辭是指凡兩件或兩件以上的事物中有類似之點，說話、作文時，將這些「類似之點」拿來打比方，使內容更生動，也更易理解。下列文句，何者有相同用法？", "ans": "B", "opts": [["A", "娛樂食物多含高熱量、高脂肪、高鹽", "類疊。"], ["B", "每一顆粉圓溜進嘴裡都像一次甜蜜的吻", ""], ["C", "怪不得珍珠奶茶能有獨特的茶香，現泡現賣", ""], ["D", "粉圓倘徉在茶湯中，吸吮入嘴，輕柔撫觸舌尖", "轉化。"]]}, {"n": 7, "q": "下列(甲)、(乙)、(丙)文中，□□□□內最適合填入的詞語依序是：<div class='aq-sub'>(甲)　鹹湯圓作法分兩道手續：揉糯米為圓，在滾水中煮至浮起。分開炒製香菇、蝦米、肉絲、韭菜、蔥，以塑造每種食材不同的效果，炒妥後加入雞高湯，起鍋時另撒些油蔥酥。湯圓和配料分道治理，□□□□。<br>(乙)　第二天，我們在島上的餐廳吃到□□□□極頂美味的「雲丹丼」，看著熱騰騰白飯上堆疊豪華山積的金色雲丹，才對原隻上菜的海膽有了不一樣的理解。<br>(丙)　□□□□的夏天，手上一杯冰涼的手搖飲，是人生的小確幸。……手搖茶，一場飲茶小革命、也正是臺灣的驕傲。飄洋過海的珍珠奶茶成為知名的現代臺灣味。</div>", "ans": "B", "opts": [["A", "殊途同歸／沒沒無聞／汗流浹背", ""], ["B", "殊途同歸／聞名遐邇／揮汗如雨", "(甲)由「鹹湯圓作法分兩道手續」、「湯圓和配料分道治理」可推知「鹹湯圓」這道料理是先分開製作再合而為一，填入「殊途同歸」較適合。出自焦桐〈鹹湯圓〉。(乙)由「極頂美味的『雲丹丼』」可推知美食多半遠近知名，填入「聞名遐邇」較適合。出自詹宏志〈驚喜的晚餐〉。(丙)由「夏天」可推知炎熱的天氣會讓人汗流很多，雖填入「揮汗如雨」、「汗流浹背」皆可，但確認(甲)、(乙)文可選填的詞語，答案應選(B)。出自潘美玲〈飲．憂：台灣手搖茶的杯底乾坤〉。<br>殊途同歸：方法或途徑不同，但最後結果卻相同。／沒沒無聞：沒有名氣。／汗流浹背：指汗流很多，溼透了背部。／聞名遐邇：不論遠近，莫不知其名聲。指名氣很大。／揮汗如雨：形容汗水流下來的很多。／南轅北轍：比喻行動和目的彼此背道而馳，或比喻遙隔兩地。"], ["C", "南轅北轍／沒沒無聞／揮汗如雨", ""], ["D", "南轅北轍／聞名遐邇／汗流浹背", ""]]}, {"n": 8, "q": "政府提出「食安五環」政策，從各個面向加強食安管理，包括：源頭控管、重建生產管理、加強查驗、加重黑心廠商責任、全民監督食安。下圖為第五環示意圖，關於此圖，下列敘述何者最適當？<img src='img/珍珠奶茶/a7442775b9034eac.png' style='max-width:100%;display:block;margin:10px auto;width:420px' alt=''><div class='aq-src'>（資料來源：行政院食品安全辦公室）</div>", "ans": "C", "opts": [["A", "「1919」是全國食安專線，在 109 年 12 月正式啟用", "「1919」是全國食安專線，在 104 年啟用。"], ["B", "某雞排店經員工檢舉使用過期香辣粉，所有店員都要受罰", "並未提及員工都要受罰，且員工檢舉可領取吹哨獎金。"], ["C", "食安專線啟用至 113 年 12 月接聽率逾八成以上，滿意度更逾九成以上", ""], ["D", "某店因使用未核准之添加物，被罰鍰 20 萬元，檢舉人可領到 1 萬元獎金", "某店被罰鍰 20 萬元，檢舉人可領到獎金 10～15 萬元。"]]}], "handoutV2": [{"title": "一、作者與題解", "page": "", "blocks": [["text", "mj", "壹　課文重點整理"], ["table", "", [["當代飲食文學的重要推手──焦桐"], ["籍貫", "高雄人"], ["本名", "葉振富"], ["生平", "文化大學 戲劇系、藝術所碩士畢業，輔仁大學 比較文學研究所博士班肄業<br>擁有作家、創業家、美食家、教育家等多重身分<br>曾任教中央大學 中國文學系，退休後專事寫作<br>成立「二魚文化」，創辦飲食雜誌，為當代飲食文學的重要推手"], ["創作風格", "關注食安問題，強調健康的飲食觀念，重視下一代飲食文化的教育<br>詩作題材多元，意象鮮明，善用戲謔手法嘲諷政治<br>散文藉自身飲食經驗，書寫食後感懷與賞評，探索社會議題及人生況味，充滿人文情懷<br>在語言表達上既細膩又生動，富有詩意和想像力，無論是詩歌還是散文，皆善於捕捉生活中的細節和情感"], ["評價", "1980年，以懷孕的阿順仔嫂獲得第三屆時報文學獎敘事詩優等獎<br>1994年，以失去地址的人榮獲第十六屆聯合報文學獎報導文學獎第一名"], ["著作", "詩集：完全壯陽食譜、青春標本、焦桐詩集：1980～1993<br>散文：暴食江湖、臺灣肚皮、味道福爾摩莎、慢食天下"], ["題解要旨", "「珍珠奶茶」是臺灣最具代表性的手搖茶飲，近年來更風靡國際，在亞洲、歐洲、美國乃至中東國家流行，成為臺灣文化的一部分，既創新也帶動臺灣茶飲的國際化<br>本文介紹珍珠奶茶的起源發展、飲用方式及文化意義，並探討伴隨著流行而出現的食安問題"]]]]}, {"title": "二、飲食文學概述　(一)定義", "page": "", "blocks": [["table", "", [["廣義", "泛指一切與飲食相關的寫作活動與文字作品，即所謂「飲食書寫」。"], ["狹義", "必須具備文學創作的特質，不僅寫下飲食的內容、形式，還必須蘊藏作者的情感與思想，傳達情境、美感或文化的意涵，也必須具有創意。"]]]]}, {"title": "(二)古代", "page": "", "blocks": [["table", "", [["時代", "說明"], ["先秦", "詩經、楚辭、禮記和儀禮等皆有對古代飲食制度、風俗文化的記載。"], ["魏 晉<br>南北朝", "關注生活品味的追求，於飲食中寄托自我志趣，藉飲酒美食以避世或自處，故出現眾多歌詠飲食的言談及作品：陸機有「千里蓴羹，未下鹽豉」之見；張翰以「蓴鱸之思」掛冠求去，並言「使我有身後名，不如即時一杯酒」名句。"], ["唐 宋", "唐 段成式 酉陽雜俎一書記載各地飲食傳聞、特色菜肴；宋 陶榖 清異錄記述飲食相關的器具、品饌等；蘇軾 豬肉頌對於自身飲食的愛好直言不諱。"]]]]}, {"title": "(三)近現代演變", "page": "", "blocks": [["table", "", [["年代", "概況", "重要作家與作品"], ["日治時期", "首次有「臺灣料理」這個名詞的誕生，當時強調臺灣料理的特殊性已與中國料理有所差異，這類專欄寫作，可以說是臺灣本土飲食書寫的濫觴。", "吳江山在臺灣日日新報開展有關臺灣料理的專欄寫作"], ["1950～1970", "1949年國民政府遷臺，大批外省族群面對漂泊異鄉、遠離故土的情緒，將思鄉情懷寄託在對故國的飲食記憶中，因此許多飽含懷鄉情感、書寫故鄉飲食記憶的散文出現在不同的報刊中。", "劉枋：烹調漫談、中央日報副刊「家鄉味」專欄<br>朱介凡：閒話吃的藝術（臺灣飲食散文史上歷時最久、作者和篇數最多的飲食散文合集）"], ["1970～1980", "從懷鄉書寫淡化為憶舊情感，但知識性提高，對飲食的歷史考證增加，也觀察社會變遷下飲食產業的發展和飲食習慣的改變，承認臺灣已成為不是故鄉的故鄉，為飲食散文書寫的轉型開發一條新的道路。", "林海音母女合編中國豆腐<br>劉震慰 故鄉之食<br>唐魯孫 吃在北平<br>梁實秋 雅舍談吃<br>逯耀東 祇剩下蛋炒飯、已非舊時味"], ["1990～1998", "作家本土化，書寫題材更加多樣化。在文學寫作中，一篇文章可能同時具備多重題材。", "凌拂 食野之苹：臺灣野菜圖譜<br>盧非易 飲食男"], ["1999至今", "1999年焦桐與林水福策劃、行政院 文化建設委員會（今文化部）舉辦的首屆「飲食文學國際研討會」正式帶出「飲食文學」的概念，自此「飲食文學」的類型增多，內容呈現多元面向、產量也快速的發展，作家們皆有獨特的切入點與觀察面向。", "林文月 飲膳札記<br>焦桐 臺灣味道<br>蔡珠兒 紅燜廚娘<br>韓良憶 羅西尼的音樂廚房<br>徐國能 第九味"]]]]}, {"title": "(四)特色", "page": "", "blocks": [["text", "para", "1. 強調感官印象的描述：對食物的外觀、口感及味道進行細緻的描述，凸顯感官體驗與影響。"], ["text", "para", "2. 提供食譜或烹飪方法：詳細說明做法，並附上獨家祕訣，增添親切感與實用性。"], ["text", "para", "3. 探討飲食與人生的關聯：通過聯想、回憶和反思飲食與人生的關係，使文字更具深度和內涵。"], ["text", "para", "4. 深入觀察本土與異國文化：能引導讀者了解特定文化的深層內涵。"], ["text", "para", "5. 以實踐引領飲食文學的風潮：作家將寫作與烹飪融合，增強說服力，同時展現創意精神。"]]}, {"title": "三、課文深究　(一)文本透視鏡", "page": "", "blocks": [["table", "", [["寫作<br>背景", "本文節選自臺灣肚皮，與臺灣味道、臺灣舌頭合為「臺灣味道三部曲」。三部曲是有系統、有目標的書寫，企圖將臺灣特有的「味道」，鮮活的保存並介紹，內容包含對於情感記憶與飲食經驗的描述、歷史與文化知識的傳遞、社會觀察與感悟等，展現完整且深入的知識內涵和審美體驗。在臺灣肚皮中，焦桐認為臺灣的飲食文化是一個混血的肚皮，融合來自四面八方的影響以及本地的獨特發展。書中逐一介紹臺灣各地小吃、茶飲，透過日常庶民飲食的深刻觀察，及其背後動人故事，帶領讀者一窺臺灣雜揉四海、兼容並蓄的文化面貌。<br>珍珠奶茶延續焦桐一貫情感豐沛和人文關懷的寫作風格，他認為飲食不僅僅是為滿足生理需求，更是一種文化修養和生活藝術，他也擔憂現代食品工業中普遍存在的添加劑和過度加工，會影響消費者的健康，所以他主張要選擇天然的食材，才能擁有健康的飲食。"]]], ["table", "", [["結構", "段落", "旨意", "讀見真相"], ["起<br>發明<br>與<br>製作", "第一段", "介紹珍珠奶茶的發明與變化", "一九八○年代發明珍珠奶茶，四十年來形式變化不大，但口味和茶品種類多樣化"], ["", "第二段", "描述珍珠（粉圓）的製作材料和方法及相關產品", "珍珠（粉圓）的傳統製法與原料經過創新改造後，呈現產品的多樣化<br>(後來發展出類似產品──<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">青蛙</span></span>下蛋、波霸奶茶"]]], ["table", "", [["承<br>歷史<br>背景", "第三段", "奶茶的歷史起源、養生功效及<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">清代</span></span>皇室對奶茶的敬重", "起源", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">文成公主</span></span>帶茶入藏，奶茶在藏族普及"], ["", "", "", "營養<br>價值", "<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">(解腥去膻、(清內熱<br>(緩解營養失調、(緩解消化不良</span></span><br>（可複選）"], ["", "", "", "歷史<br>地位", "<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">清代</span></span>由皇室祭祀、宮廷禮儀顯現出對奶茶的敬重"], ["", "", "", "文化<br>載體", "不僅是一種飲品，還具有一定的文化和醫療價值"]]], ["table", "", [["承<br>製作<br>方式<br>與<br>美味<br>關鍵", "第四段", "珍珠奶茶的製作過程與美味關鍵", "強調珍珠奶茶的品質和美味關鍵在於選用新鮮香醇的奶茶、用小桶現泡現賣的茶，並用<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">雪克器</span></span>搖茶，加上珍珠的口感要有彈勁、不可黏稠，如此才能保證珍珠奶茶的美味和口感"]]], ["table", "", [["承<br>全球<br>影響", "第五段", "珍珠奶茶在國內外的流行及發源店的爭議", "臺灣", "隨處可見店家，非常普及"], ["", "", "", "國際", "亞洲、歐洲、美國甚至中東國家"], ["", "", "", "發明權<br>爭議", "春水堂、翰林茶館皆未申請專利<br>→凸顯<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">智慧財產權</span></span>的重要性"], ["轉<br>品質<br>問題", "第六段", "從珍珠奶茶中的添加物問題延伸至<span class=\"jy-cir\">⑧</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">食安</span></span>問題，皆對消費者的健康造成影響", "品質<br>關注", "批判商家粉圓與奶茶的添加劑、人造奶精等問題"], ["", "", "", "消費者<br>健康", "人工添加物、塑化劑對消費者的健康造成潛在的危害"], ["轉<br>價格<br>與<br>價值", "第七段", "食品價格與安全須具備合理性", "食品的<br>合理性", "「用化學藥劑促長的香菇，3個月即可收成；以自然農耕法培育的香菇需費時12個月才能收成，它們的價格豈能一樣」<br>→使用化學藥劑促長香菇的主要原因是加速生長過程，從而提高生產效率和降低成本。雖然使香菇的生長周期大幅縮短，但這種香菇在質地和口感上較差，且可能殘留有害物質，對消費者健康構成潛在風險"], ["", "", "", "餐館<br>價格<br>合理性", "「頂級餐館的獲利，往往遠不如一般連鎖餐館」<br>→頂級餐館成本高，使用昂貴食材及精細的料理和高標準服務，通常處於高端市場定位，但市場有限且競爭激烈，獲利相對較低。連鎖餐館則依賴規模效益和標準化運作，能在大規模營運中獲得較高利潤"], ["", "", "", "飲食<br>之道", "「學習知味辨味，理解食物及其操作」<br>→提升對食物的品味與要求"], ["", "", "", "理解<br>價格<br>與<br>價值<br>的差異", "作者使用比較法，通過比較不同生產方式的食品，強調價格與品質的關係，高品質食品需要更多的時間和資源，價格自然較高，而廉價食品可能在安全和品質上有所欠缺。所以食品價格應該合理反映其品質和安全性，消費者應重視食品的內在價值和品質，而非僅僅關注價格"], ["合<br>搭配<br>美感", "第八段", "總結珍珠奶茶的獨特魅力及其美好的口感", "粉圓<br>與<br>奶茶", "將珍珠奶茶的美妙口感和搭配美感，與其他經典食物搭配相比較，讚美珍珠奶茶獨特的味覺體驗，奶泡與茶香快樂的平衡"], ["", "", "", "粉圓<br>的<br>感官<br>享受", "當高品質的奶茶和珍珠（粉圓）之間達到平衡與融合，品嘗時就如同甜蜜的吻，令人愉悅"]]]]}, {"title": "(二)文本異世界", "page": "", "blocks": [["table", "", [["主旨", "本文描寫珍珠奶茶的製作過程及其在臺灣日常生活中的地位，它不僅是一種飲品，更是臺灣文化的一部分。文章討論珍珠奶茶在全球流行，成為臺灣文化的象徵之一，反映出臺灣在國際上的影響力。焦桐的文字讓讀者更加理解這款飲品背後的歷史、文化和情感，彰顯飲食文化與人文關懷的緊密聯繫，並揭示<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">食安</span></span>問題的嚴重性，引發讀者深刻的省思"], ["文體", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">飲食</span></span>文學"]]], ["table", "", [["寫作特色", "綜觀古今歷史文化", "透過回顧歷史，探討奶茶可能的起源，說明奶茶在中國文化中的地位和價值；並以珍奶流行國際，凸顯其掀起的風潮。"], ["", "結合健康養生價值", "從中醫的角度分析奶茶的養生價值，指出奶茶幫助北方游牧民族改善消化不良、營養失調的問題，從而探討飲食與健康的關係"], ["", "揭示食品安全問題", "作者提及商家為追求利潤，在珍珠的製作過程中添加塑化劑等有害物質，警示消費者應關注食品安全，以維護健康"], ["", "融合情感與事實", "本文有主觀的個人觀點和情感，如對珍珠奶茶的愛好、食品安全問題的擔憂、飲食文化和商業化的反思；除此之外，也有客觀的製作過程描述，使文章更加生動和具有感染力"]]]]}, {"title": "一、形近字", "page": "", "blocks": [["text", "mj", "貳　形音義比較"], ["table", "", [["偏旁", "音", "例"], ["參", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄔㄢ</span></span>", "「摻」入"], ["", "ㄘㄢˇ", "淒「慘」、悲「慘」"], ["", "ㄘㄢ", "「驂」乘（古代乘車陪坐在右邊的人）"], ["延", "<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">一ㄢˊ</span></span>", "「筵」席、蜿「蜒」"], ["", "ㄉㄢˋ", "「誕」辰"], ["", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄒㄧㄢˊ</span></span>", "垂「涎」三尺"], ["夬", "<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄇㄟˋ</span></span>", "連「袂」前往"], ["", "ㄐㄩㄝˊ", "玉「玦」、「訣」別、「抉」擇"], ["朔", "<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄙㄨˋ</span></span>", "「塑」膠、推本「溯」源"], ["", "<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄕㄨㄛˋ</span></span>", "橫「槊」賦詩、「朔」日"], ["叚", "ㄒㄧㄚˊ", "「瑕」疵、閒「暇」、名聞「遐」邇"], ["", "ㄐㄧㄚ", "蒹「葭」"], ["來", "<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄌㄞˊ</span></span>", "招「徠」"], ["", "ㄌㄞˋ", "青「睞」"]]]]}, {"title": "二、一字多音", "page": "", "blocks": [["table", "", [["字", "音", "例"], ["膻", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄕㄢ</span></span>", "腥「膻」"], ["", "ㄉㄢˋ", "「膻」中"]]]]}, {"title": "轉化", "page": "", "blocks": [["text", "mj", "參　修辭"], ["text", "para", "描述一件事物時，轉變其原來性質，故意把物當做人（擬人法、人性化）、把人當做物（擬物法、物性化），或者把抽象事物當做具體事物來描寫（擬形法、形象化），這種修辭格稱為「轉化」，也稱為「比擬」。"], ["table", "", [["類別", "定義", "例句", "說明"], ["擬人<br>（人性化）", "把人類的心情投射於外物，將外物看成與人類一樣，而加以描述，使具有人類的動作、行為、思想、感情等", "粉圓徜徉在茶湯中，吸吮入嘴，輕柔撫觸舌尖，滑動。", "「徜徉」、「撫觸」使粉圓人性化"], ["", "", "當不會忘記，白胖的水煎包，是如何蹲坐在圓形平底鍋上，齊聲唱著「嗞嗞嗞」的快樂頌。<br>（陳幸蕙 黎明心情）", "「蹲坐」、「唱著」使水煎包人性化"]]], ["table", "", [["擬物<br>（物性化）", "把人當做其他動物、植物，甚至無生物來描述", "我提筆的手勢擱淺在半空中。<br>（簡媜 夏之絕句）", "「擱淺」使人轉化為船"], ["", "", "別人是用兩隻腳走路，他卻是長著翅牓飛的。<br>（蘇雪林 我所認識的詩人徐志摩）", "「長著翅牓」使人轉化為鳥"], ["擬形<br>（形象化）", "把抽象事物或觀念，化為具體的形象", "心裡正有一種歲月悠悠的沉鬱，壓在那裡，不由分說。<br>（楊牧 十一月的白芒花）", "「壓在那裡」將心裡的沉鬱形象化成為具體事物"], ["", "", "那就折一張闊些的荷葉／包一片月光回去／回去夾在唐詩裡。<br>（余光中 滿月下）", "「包、夾」將月光形象化，當做具體事物"]]]]}, {"title": "一、成語", "page": "", "blocks": [["text", "mj", "肆　延伸學習"], ["table", "", [["成語", "釋義", "例句"], ["饞涎欲滴", "形容貪食的樣子。", "阿偉是臺灣小吃迷，只要看到熱騰騰的滷肉飯便饞涎欲滴。"], ["垂涎三尺", "形容非常貪饞或看見別人的東西極想據為己有。", "晶瑩剔透的珍珠粉圓搭配翠綠的抹茶，令人垂涎三尺。"], ["齒頰留香", "形容食物味道鮮美，令人回味無窮。", "這家炸雞排，肉質鮮嫩多汁，一入口便覺齒頰留香。"], ["炊金饌玉", "形容飲食的豐盛美味。", "這家餐廳的菜品炊金饌玉，水陸佳餚道道都是藝術品。"]]]]}, {"title": "二、名句", "page": "", "blocks": [["text", "para", "1. 人生果然像茶葉蛋，偶有傷痕與毀壞，像烹煮的茶葉，略帶苦澀；苦中帶甘，苦中作樂。微笑中閃著淚光。 （焦桐 茶葉蛋）"], ["text", "para", "2. 蛋殼的裂痕是一則隱喻。人生的傷痕亦然。 （焦桐 茶葉蛋）"], ["text", "para", "3. 一碗牛肉麵的屬性宛如一段旋律，我漸漸相信，天下美食都力求臻於音樂的境界，通過身體的味覺和消化系統，使精神達到幸福的狀態。 （焦桐 論牛肉麵）"], ["text", "para", "4. 豬血糕啟示我們：最有分量、最令人驚嘆的菜肴，是凝練的菜肴，這種菜肴刪掉了一切多餘的東西，一切可以不出現的東西；只保留非出現不可的東西。這就是自然質樸。 （焦桐 豬血糕）"], ["text", "para", "5. 飲凍頂烏龍，好像在追求內心的平靜，總是詩意衝動。我甚至覺得茶湯是感情，敏銳吾人的心神，美好的記憶逐一蘇醒，過去和現在交談。 （焦桐 凍頂烏龍茶）"], ["text", "para", "6. 番薯粥是粥中之質樸者，一介布衣的樣子。它很隨和，很坦白，很善良，可以簡單搭配豆腐、蛋、醬菜，也可以豪華到有魚有肉有鮮蔬。貧困的年代喝粥，令粥顯得寒磣；小康時吃粥，總是帶著閑適感、謙遜而健康的暗示。 （焦桐 番薯粥）"]]}, {"title": "三、相關作品欣賞", "page": "", "blocks": [["text", "para", "(一)"], ["table", "", [["(甲)　龍焙今年絕品，谷簾自古珍泉。雪芽雙井散神仙。苗裔來從北苑。<br>湯發雲腴釅白，盞浮花乳輕圓。人間誰敢更爭妍。鬥取紅窗粉面。<br>（蘇軾 西江月 茶詞）<br>(乙)　鳳舞團團餅。恨分破、教孤令。金渠①體淨，只輪慢碾，玉塵光瑩。湯響松風，早減了、二分酒病。　味濃香永。醉鄉路、成佳境。恰如燈下，故人萬里，歸來對影。口不能言，心下快活自省。                                       　　   （黃庭堅 品令．茶詞）<br>（注：①金渠：指碾磨茶葉的器具，金屬所製。）"]]], ["text", "q", "【(B)】1.關於(甲)、(乙)二詞的觀點，下列敘述何者正確？"], ["text", "opt", "(A)(甲)詞藉朵朵花瓣來形容茶杯的外型輕盈圓潤"], ["text", "opt", "(B)(甲)詞以女子的嬌美容顏來比喻茶湯色澤之美"], ["text", "opt", "(C)(乙)詞用印有鳳舞圖案的茶餅來比喻夫婦和睦"], ["text", "opt", "(D)(乙)詞認為飲茶的妙處可用文字、言語來表達"], ["text", "exp", "【解析】(A)(甲)詞描寫茶杯上漂浮著如花般的茶沫輕盈而圓潤。(C)鳳舞團團餅：意指龍鳳團茶中的鳳餅茶。印有鳳舞圖案的鳳餅茶是宋代御貢名品，茶中之尊，名冠天下。(D)由「口不能言，心下快活自省」可知(乙)詞認為飲茶的妙處只可意會，不能言傳。"], ["text", "q", "【(A)】2.關於(甲)、(乙)二詞寫作手法的解說，何者最適當？"], ["text", "opt", "(A)(甲)詞「散神仙」：意指茶香四溢，有如仙人的氣息散落"], ["text", "opt", "(B)(乙)詞「湯響松風」：以松林風的響聲，形容茶味的純香"], ["text", "opt", "(C)二詞皆詳細記述茶的發源地、歷史背景與茶具製造過程"], ["text", "opt", "(D)二詞皆以「故人相會」蘊染出作者念舊懷鄉的滄桑之感"], ["text", "exp", "【解析】(B)(乙)詞「湯響松風」：意指烹茶湯沸發出的響聲，猶如風吹過松林。(C)二詞皆未詳述茶的發源地、歷史背景與茶具製造過程。(D)(甲)詞未以「故人相會」蘊染出作者念舊懷鄉的滄桑之感。(乙)詞由「恰如燈下，故人萬里，歸來對影」可推知。"], ["text", "q", "【(A)】3.依據(甲)、(乙)二詞，下列關於①、②的研判應是："], ["text", "para", "①宋代尚茶、愛茶、品茶的文化十分興盛。"], ["text", "para", "②展現蘇、黃詞人對茶的讚美及生活情趣。"], ["text", "opt", "(A)①、②皆正確　 (B)①、②皆錯誤　 (C)①正確，②錯誤　 (D)①錯誤，②正確"], ["text", "exp", "【解析】(A)①(甲)詞由「龍焙今年絕品，谷簾自古珍泉」、「湯發雲腴釅白」、(乙)詞由「鳳舞團團餅。恨分破、教孤令。金渠體淨，只輪慢碾，玉塵光瑩」，可知二詞中皆描寫了宋代對茶的喜愛及品茗文化盛行，故研判正確。②(甲)詞由「龍焙今年絕品，谷簾自古珍泉。雪芽雙井散神仙。苗裔來從北苑」、(乙)詞由「味濃香永。醉鄉路、成佳境。恰如燈下，故人萬里，歸來對影」，可知二詞皆展現蘇、黃詞人對茶的讚美及生活情趣，故研判正確。"], ["text", "trans", "【語譯】(甲)今年的龍焙茶品質絕佳，谷簾水自古以來被視為珍貴的泉水。雙井雪芽茶的茶香四溢如仙人的氣息散落。此茶是來自北苑貢茶的苗裔。泡出來的茶湯像雲一樣醇厚，味道濃郁且顏色潔白，茶杯上漂浮著如花般的茶沫輕盈而圓潤。在這人間又有誰能比這茶更美呢。茶湯的色澤就像爭豔的女子嬌美的容顏。"], ["text", "para", "(乙)鳳餅茶上印有幾隻旋轉飛舞的鳳凰。可恨的是有人把茶餅碾破磨碎了，讓鳳凰獨自孤零零的。用乾淨的金色碾磨茶具，將茶餅細心慢慢碾成瓊粉玉屑，只見茶末成色純淨，清亮晶瑩。加入好水煎之，烹茶湯滾沸所發出的響聲如風吹過松林，早已經減了二分醉酒之意。　煎好的茶水味道醇厚，香氣久遠。飲茶也能使人醉，但不僅沒有醉酒的苦意，反而覺得精神爽朗，漸入佳境。就好像是獨自對著孤燈，老朋友從萬里之外，趕來相會。這種妙處只能心領神會，無法用言語說清楚，內心快活只有飲者才能體會其中的情味。"]], "layout": "split"}, {"title": "(二)想喝什麼茶？談盲買與忙買（節錄） 小令", "page": "", "blocks": [["table", "", [["茶葉即課本<br>剛學茶的時候，不知道為什麼只想喝老茶，也許覺得老茶珍貴，喝茶的同時，常升起一股感恩涕淚、法喜充滿的洗滌之感，頗有淨化身心之效。但那時還不懂茶，客觀回想，應是心理作用多於生理作用。<br>深層的情緒需要宣洩的出口，居然花錢仰賴外物，且懂茶之後，發現買到的其實是假的老茶，不住大驚失色：居然還花錯錢！<br>買茶買錯時，會互相安慰說就當作「繳學費」，在驚駭與憤怒的複雜情緒消散過後，也會冷靜平復，把假的老茶留下來當樣本（茶葉即課本）。<br>「假的」一詞令人敏感，但當初買這支茶的故事，是我們三個剛學茶的新手，為了尋找老茶，終於問到一間店有賣，再追問能否試喝，店家看似為難，收走原本給我們聞跟看的茶樣，□□□□說只能試喝三泡，我們□□□□試完三泡，就買了。說真的，如果不懂老茶，依舊是一種亡目（盲盲的感覺），試或不試，我們都還是會□□□□，合資買下去。<br>一般來說，老茶最為人所知的香氣，在現代的製茶工藝下，都能夠仿擬成真。畢竟老茶量少，喝茶的需求過多，供不應求，喝一泡就少一泡。市面上出現模仿老茶香氣滋味的（假老）茶，也是在服務喝茶的饕客需求。<br>偏偏真假之間的價差太大，充滿驚人的利潤空間，導致賣家若說這是老茶，可能沒有一併告知買家括號內的隱藏資訊。<br>老茶一方面貴在量少，一方面貴在時間，二十多歲的我妄想要喝懂三四十年的老茶，我的內心再怎麼裝老，也不會真的懂。就算現在三十多歲的我，要去喝懂我出生前的年分的老茶（譬如1980），我還是只能獃站在歷史的洪流面前，嚅囁地說：不好意思，我還小我還小。<br>喜歡最重要<br>不再追求老茶後，我因為不同的機緣而陸續喜歡過東方美人、鐵觀音、高山茶等，現在日常則習慣喝包種茶或白茶。偶爾要配甜點或飯後解膩的話，會選擇紅茶或普洱。最近一次跟朋友去買茶，是因為朋友「好奇」，所以一起前往茶莊。老闆很客氣，問我們想喝什麼茶，都可以試喝。結果朋友每支茶都好奇，從頭喝到尾，幾乎整間店喝遍。<br>朋友最後喝到「茶醉」。有人會認知「茶醉」是低血糖，譬如喝餓或喝到手抖頭痛，或心悸不適。造成茶醉的原因很多，但為了試茶，身體短時間中接觸到的茶品紛雜，就算依照發酵度或焙火度，從清香類喝到濃郁類，都不是一般人在幾小時內，會把這麼多茶湯放進身體裡的正常行為。"]]], ["text", "q", "【(B)】1.依據上文，關於「茶葉即課本」的說明，何者理解不適當？"], ["text", "opt", "(A)喝老茶時如聽聞佛法，內心充滿喜悅、洗滌之感"], ["text", "opt", "(B)老茶有淨化身心之效，可改善心理、生理的健康"], ["text", "opt", "(C)買錯茶，當作繳學費，把假的老茶留下來當樣本"], ["text", "opt", "(D)老茶真假之間的價差太大，充滿驚人的利潤空間"], ["text", "exp", "【解析】(A)由「老茶珍貴，喝茶的同時，常升起一股感恩涕淚、法喜充滿的洗滌之感」可知。(B)文中只提到老茶「頗有淨化身心之效」，未敘寫老茶可改善心理、生理的健康。(C)由「買茶買錯時，會互相安慰說就當做『繳學費』，在驚駭與憤怒的複雜情緒消散過後，也會冷靜平復，把假的老茶留下來當樣本（茶葉即課本）」可知。(D)由「（老茶）偏偏真假之間的價差太大，充滿驚人的利潤空間」可知。"], ["text", "q", "【(A)】2.依據上文，□內最適合填入的詞語依序為何？"], ["text", "opt", "(A)半推半就／歡天喜地／咬緊牙根"], ["text", "opt", "(B)滿腔熱忱／欲就還推／出手大方"], ["text", "opt", "(C)半推半就／欲就還推／出手大方"], ["text", "opt", "(D)滿腔熱忱／歡天喜地／咬緊牙根"], ["text", "exp", "【解析】由「我們三個剛學茶的新手，為了尋找老茶，終於問到一間店有賣，再追問能否試喝，店家看似為難，收走原本給我們聞跟看的茶樣」，可知店家假意推辭，使用半推半就的行銷手法，引我們試茶，故填入「半推半就」／由「試完三泡，就買了」，可知是試喝老茶之後十分滿意，填入「歡天喜地」文意最適當／由「試或不試，我們都還是會……，合資買下去」，可知共同出資是因為老茶價格昂貴，忍受價錢昂貴的痛苦而合資購買，填入「咬緊牙根」文意妥切，故答案選(A)。(A)半推半就：心中早已同意，表面上卻不答應，表現出假意推辭的姿態／咬緊牙根：比喻忍受痛苦而堅持到底。(B)欲就還推：想要接受、靠近，又覺不好意思。"], ["text", "q", "【(D)】3.依據上文，關於老茶的敘述，下列何者正確？"], ["text", "opt", "(A)作者深懂品味1980年分的老茶，並且帶動購買、飲用老茶的風氣"], ["text", "opt", "(B)作者不再獨鍾老茶後，日常習慣喝紅茶、普洱，以白茶配甜點解膩"], ["text", "opt", "(C)一般認為「茶醉」是因喝了太多老茶，造成血糖升高所引起的不適"], ["text", "opt", "(D)老茶價錢昂貴的原因是一方面貴在量的稀少，一方面貴在時間的長遠"], ["text", "exp", "【解析】(A)由「就算現在三十多歲的我，要去喝懂我出生前的年分的老茶（譬如1980），我還是只能獃站在歷史的洪流面前，嚅囁地說：不好意思，我還小我還小」，可知作者尚未深懂品味1980年分的老茶，文中亦未提及作者帶動購買、飲用老茶的風氣。(B)由「我因為不同的機緣而陸續喜歡過東方美人、鐵觀音、高山茶等，現在日常則習慣喝包種茶或白茶。偶爾要配甜點或飯後解膩的話，會選擇紅茶或普洱」，可推知日常習慣喝包種茶、白茶，以紅茶或普洱配甜點解膩。(C)由「有人會認知『茶醉』是低血糖，譬如喝餓或喝到手抖頭痛，或心悸不適」可知為非。"], ["text", "para", "【賞析】本文藉由作者自身的品茶歷程，寫出從盲目追求「老茶」，到自在尋味「喜歡」的心路轉變。作者先以輕鬆的筆調，敘述學茶新手的誤買經驗，以及真假難辨的茶市現實；「茶葉即課本」一語，點出每一次經驗都是學習。後段則敘述不再追求老茶後，因緣分品嘗不同的茶類，形成個人偏好，展現「喜歡最重要」的從容態度。"]], "layout": "split"}, {"title": "伍 統測試題精選", "page": "", "blocks": [["text", "mj", "伍　統測試題精選"], ["text", "para", "1.閱讀下文，回答第(1)、(2)題。 【112統測】"], ["text", "para", "米飯總帶著樸素的美感，自足而清純。袁枚說：「飯之甘，在百味之上，知味者，遇好飯不必用菜。」飯如果優秀，不必佐任何菜肴，即滋味無窮。"], ["text", "para", "米的天性既純真又深情，跟什麼水結合，加熱，就變成什麼飯。若用雞汁煮飯，即煮出雞飯；加入薑汁，則煮出薑飯；加入檸檬汁，就是檸檬飯；加入椰漿，自然呈現椰漿飯；加入墨魚汁，將變出烏亮的墨魚飯。"], ["text", "para", "不過也並非每種米皆如此。如長米有點像騎牆派，蒸煮後不具黏性，顆粒各自獨立，善變，不強調自我，適合用來製作各式菜飯或炒飯。香米則個性拘泥，堅持主體性，烹煮時會散發芳香，不宜添加咖哩、椰汁、番茄等外物。"], ["text", "para", "吃飯很像家居生活，平常地位低落，往往忽略其存在，名稱明明叫「主食」，卻成附屬品，講究的飯館往往專吃各式菜肴，不配一口飯。白飯之於佳肴，好比畫布之於色彩和線條，一席筵宴總不乏華麗的菜肴，互相爭奇鬥豔，但若缺少白飯的搭配調和，不免彼此扞格。"], ["text", "para", "（改寫自焦桐 論吃飯）"], ["text", "q", "【(C)】(1)上文所述長米蒸煮後所呈現的特性，與何者最接近？"], ["text", "opt", "(A)批大郤，導大窾，因其固然"], ["text", "opt", "(B)大行不顧細謹，大禮不辭小讓"], ["text", "opt", "(C)聖人不凝滯於物，而能與世推移"], ["text", "opt", "(D)人工繼晷以襄事，豈好勞而惡逸哉"], ["text", "exp", "【解析】(C)由長米的性質「顆粒各自獨立，善變，不強調自我」與「聖人不凝滯於物，而能與世推移」能隨俗推移最相近。"], ["text", "trans", "【語譯】(A)用刀從筋骨相連的縫隙劈開，順著骨骼間的空隙切入，依照牛體本來的結構。莊子 庖丁解牛。(B)做大事的人不須拘泥細微的末節與謹慎的小事，行大禮的人不須講究處處謙讓。司馬遷 鴻門宴。(C)聖人不執著於任何事物，能隨著世俗而進退應變。屈原 漁父。(D)人們卻點油燈夜以繼日完成工作，難道是這些人愛好勞動而厭惡安閒嗎？宋應星 天工開物 膏液緒言。"], ["text", "q", "【(B)】(2)上文對「米的天性既純真又深情」、「白飯之於佳肴，好比畫布之於色彩和線條」的解說，依序相當於下圖的哪個理由？"], ["text", "para", "<img src='img/珍珠奶茶/fef784fd3005ff04.png' style='max-width:100%;width:460px;display:block;margin:10px auto' alt=''>"], ["text", "opt", "(A)①、④　　(B)②、③　　(C)②、④　　(D)③、⑤"], ["text", "exp", "【解析】(B)「米的天性既純真又深情」旨在說明米飯能夠與各種食材結合，成為不同料理，相對應②米食種類變化多的理由；「白飯之於佳肴，好比畫布之於色彩和線條」旨在說明透過白飯的調和搭配，讓一桌的佳餚美味可口，相對應③飯讓桌菜呈美味的理由。"], ["text", "q", "【(A)】2.依據下文，□□□□內最適合填入的詞語依序為何？ 【109統測】"], ["text", "para", "食物與體重，恰是天平的兩端，是造物者為了掌控人類所精心設計的一套恐怖平衡遊戲。有人如臨深淵，還知□□□□，倖能全身而退；有人□□□□，美食當前即奮不顧身，終於葬身天平彼端，成了肉體之河畔永不回頭的過河卒子。"], ["text", "para", "（改寫自古蒙仁 逆溯肉體之河）"], ["text", "opt", "(A)懸崖勒馬／食髓知味　　　　(B)懸崖勒馬／見微知著"], ["text", "opt", "(C)自給自足／食髓知味　　　　(D)自給自足／見微知著"], ["text", "exp", "【解析】由「如臨深淵」、「倖能全身而退」前後文意可知作者在敘寫食物與體重之間的平衡關係，面對食物的攝取應戒慎小心，才能及時制止食物的誘惑，保持體重；又從「美食當前即奮不顧身」、「葬身天平彼端」可知若無法抵抗美食的誘惑，一味貪享食物的美味，體重便會失去平衡，因此答案選(A)。(A)瀕臨懸崖而能及時勒住奔馬。引申為人們警悟險境，及時回頭／食得一次骨髓，便知曉其美味。比喻人得到一次好處後便貪得無厭。(B)見微知著：看到事情的些微跡象，就能知道它的真相及發展趨勢。(C)自給自足：生產和消費維持平衡，可以獨立營生，不必仰賴於人。"]], "layout": "split"}]}]);
